window.C15_BANK = {"collection": {"id": 14, "title": "Articles and Labs", "file": "PSYC301 Midterm II labs and articles", "sections": [{"page": 1, "title": "Phonological Similarity Effect", "bullets": ["The <strong>phonological similarity effect</strong>: lists of <strong>similar-sounding items</strong> are recalled <strong>worse</strong> than lists of different-sounding items, even when the items are only read silently. <strong>Acoustic similarity effect</strong> is arguably the better name.", "So people <strong>recode what they see into a speech-based form</strong>. A purely visual code would cause mix-ups between look-alikes such as E and F instead. This is the basis of the <strong>phonological loop</strong> in working memory.", "The loop has a <strong>phonological store</strong> and an <strong>articulatory control process</strong> that converts visual input to speech and refreshes traces. <strong>Articulatory suppression</strong> occupies that process, and with visually presented lists the similarity cost disappears."], "image": 0}, {"page": 2, "title": "Neighborhood Size Effect", "bullets": ["A word's <strong>neighborhood</strong> is the set of words that differ from it by one letter (orthographic) or one sound (phonological): cat is a <strong>large neighborhood</strong> word, hippopotamus a <strong>small neighborhood</strong> word.", "Roodenrys et al. (2002) found that <strong>large neighborhood words are recalled better</strong> in short-term memory tasks, so <strong>long-term memory</strong> knowledge of words helps short-term recall.", "As a result, <strong>memory span</strong> is not a pure measure of short-term capacity."], "image": 1}, {"page": 3, "title": "Brown-Peterson Task", "bullets": ["In the <strong>Brown-Peterson task</strong> people study consonants and then do a <strong>distractor task</strong>, counting backwards, that blocks rehearsal. The longer the distraction, the <strong>worse the recall</strong>.", "Because counting is so unlike remembering letters, Peterson and Peterson (1959) judged <strong>interference</strong> an unlikely cause and concluded that <strong>short-term memory (STM)</strong> loses information through <strong>decay</strong> unless it is rehearsed.", "This challenged the view, following McGeoch's (1932) critique, that forgetting is due to <strong>interference</strong>; decay is the researchers' conclusion, and Keppel and Underwood (1962) are cited for an alternative."], "image": 2}, {"page": 4, "title": "Modality Effect", "bullets": ["The <strong>modality effect</strong>: better memory for the <strong>last one or two items</strong> of a list when it is <strong>heard</strong> than when it is read silently. Lip-read or silently mouthed lists show it too.", "It strongly influenced ideas about <strong>sensory memory</strong>, a back-up store of <strong>raw, unanalyzed sensory input</strong>.", "The favored explanation (Neath and Surprenant, 2003) is that hearing adds <strong>extra information about how the list sounds</strong>, which helps the final items."], "image": 3}, {"page": 5, "title": "Partial Report", "bullets": ["Early work suggested people can report only a small part of a brief display. <strong>Sperling (1960)</strong> argued that this limit comes from <strong>recall</strong>, not perception.", "With <strong>partial report</strong>, a cue right after the display lets observers report the cued part almost perfectly, so a <strong>sensory (iconic) store</strong> briefly held nearly all of it.", "The real limit is the <strong>time needed to report</strong>: delay the cue and performance falls toward the usual limit, because the store is <strong>very short-lived</strong>."], "image": 4}, {"page": 6, "title": "Position Error Effect", "bullets": ["The <strong>position error effect</strong>: items are usually recalled in the <strong>correct position</strong>, and when they are not, the errors are <strong>systematic</strong>, with the item landing in an <strong>adjacent</strong> position.", "So order errors are not random, and scoring only percent correct hides that people keep <strong>approximate position information</strong>."], "image": 5}, {"page": 7, "title": "Mental Rotation", "bullets": ["People seem to use <strong>mental images</strong>, but <strong>self-reports of imagery are unreliable</strong>: it is impossible to tell whether the images differ or only the descriptions. So researchers use tasks that require imagery and vary a critical part of the task.", "Shepard and Metzler (1971) had people judge whether two block shapes were the <strong>same or mirror images</strong>, with one turned. People <strong>mentally rotated</strong> one shape, and the <strong>larger the turn, the longer the response</strong>, at a constant rate.", "This suggests <strong>mental images are much like real images</strong>, and it influenced <strong>theories of mental representation</strong>."], "image": 6}, {"page": 8, "title": "Typical Reasoning", "bullets": ["People judge probability with <strong>heuristics</strong> that trade accuracy for speed: usually good enough, but sometimes wrong. Tversky and Kahneman (1983) showed estimates often differ greatly from objective probability.", "The <strong>conjunction fallacy</strong> is judging that A and B together are more likely than A alone or B alone, although a combination is <strong>never more likely than</strong> either part alone.", "Shafir, Smith, and Osherson (1990) found that people sometimes rated a combination of professions or activities as more likely than one part, which points to heuristics rather than probability rules."], "image": 7}, {"page": 9, "title": "Wason Selection", "bullets": ["In the <strong>Wason Selection Task</strong>, the rule <strong>\"If a card has a D on one side, it has a 3 on the other\"</strong> is best tested with <strong>D and 7</strong>, since the 7 could <strong>falsify</strong> it. Most people choose D and 3, and the 3 can only <strong>confirm</strong> the rule.", "The same logic in a <strong>familiar thematic rule</strong> (\"If you borrow my car, you must fill up the gas tank\") is much easier: choose <strong>\"borrowed car\"</strong> and <strong>\"empty gas tank.\"</strong>", "Wason and Shapiro (1971) compared abstract and thematic rules: people test a rule well with <strong>relevant experience</strong>, and abstract rules force them to use <strong>logic alone</strong>."], "image": 8}, {"page": 10, "title": "Decision Making", "bullets": ["Decisions are <strong>influenced by many factors</strong>, and <strong>framing effects</strong> occur when the wording or context makes a big difference to a choice, <strong>even for otherwise equivalent situations</strong>. Kahneman and Tversky (1982) summarized many of them.", "The same choice can be presented in <strong>two ways</strong>. In classic framing research (Tversky and Kahneman), <strong>gain wording</strong> typically leads to the <strong>sure option</strong> and <strong>loss wording</strong> to the <strong>gamble</strong>.", "So choices can follow the framing and not the substance."], "image": 9}, {"page": 11, "title": "Monty Hall", "bullets": ["The <strong>Monty Hall 3 Door problem</strong> shows poor intuition about the probability of <strong>combinations of events</strong>. After you pick one of three doors, the host, who always plays fair this way, opens a no-prize door.", "Many people think <strong>stay or switch makes no difference</strong>, which is incorrect: you should <strong>switch</strong>, which wins about two-thirds of the time.", "Your first pick keeps its <strong>1 in 3</strong> chance, so the <strong>2 in 3</strong> held by the other two doors moves to the one remaining door."], "image": 10}, {"page": 12, "title": "Risky Decisions", "bullets": ["Risky choices depend on how outcomes are <strong>framed</strong> and perceived. In these choices people pick between a <strong>guaranteed outcome</strong> and a <strong>gamble</strong>, where the guaranteed outcome can be a gain or a loss.", "In prospect-theory research (Kahneman and Tversky), people typically <strong>avoid risk with gains</strong>, taking the sure thing, and <strong>seek risk with losses</strong>, taking the gamble.", "So decisions about risk depend on whether outcomes are seen as <strong>gains or losses</strong>, not only on the objective odds."], "image": 11}, {"page": 13, "title": "German & Defeyter (2000): Immunity to functional fixedness in young children", "bullets": ["<strong>German and Defeyter (2000)</strong> tested whether young children get stuck on an object's <strong>usual function</strong> (<strong>functional fixedness</strong>), using a box that was first shown as a container.", "<strong>Older children</strong> (6 and 7) were <strong>slower</strong> to use the box as a support after seeing it as a container; <strong>5-year-olds were not slowed</strong> and were even faster.", "Younger children seem to have a <strong>more fluid idea of function</strong>, so one demonstrated use did not lock the object in."], "image": 12}, {"page": 14, "title": "Leist et al. (2022): Irrelevant speech impairs serial recall of verbal but not spatial items", "bullets": ["<strong>Leist and colleagues (2022)</strong> studied the <strong>irrelevant speech effect</strong>: speech to be ignored <strong>impairs serial recall</strong>, more for <strong>changing-state</strong> speech than <strong>steady-state</strong> speech.", "Speech hurt <strong>verbal</strong> recall but <strong>not spatial</strong> recall, in children and adults.", "The effect is <strong>specific to verbal material</strong>, which fits <strong>phonological interference</strong> better than attention-capture or changing-state accounts."], "image": 13}, {"page": 15, "title": "Morrison & Richmond (2020): Offloading items from memory", "bullets": ["<strong>Morrison and Richmond (2020)</strong> studied <strong>cognitive offloading</strong>, using actions like writing things down to <strong>reduce mental demands</strong> (Risko and Gilbert, 2016).", "Offloading <strong>improved memory</strong>, especially at <strong>high loads</strong>, and people offloaded <strong>more as load grew</strong>.", "<strong>Memory ability did not predict</strong> who offloaded, so offloading <strong>may</strong> be a <strong>compensatory strategy</strong> across abilities."], "image": 14}, {"page": 16, "title": "Hoover & Healy (2019): The Bat-and-Ball Problem", "bullets": ["The <strong>bat-and-ball problem</strong> (Frederick, 2005): bat and ball cost $1.10 and the bat costs $1.00 more. The intuitive answer is <strong>10 cents</strong>; the correct answer is <strong>5 cents</strong>.", "<strong>Kahneman and Frederick (2002)</strong> called the error <strong>unconscious attribute substitution</strong>; <strong>De Neys and colleagues (2013)</strong> found wrong reasoners were <strong>less confident</strong> than on a control version.", "<strong>Hoover and Healy (2019)</strong> found wrong reasoners mostly <strong>remembered 'more than'</strong> and because substitution cannot be confirmed as the cause of the error, they call the sensitivity <strong>error sensitivity</strong>."], "image": 15}, {"page": 17, "title": "Giuliani et al. (2023): The joint effect of framing and defaults on choice behavior", "bullets": ["<strong>Giuliani and colleagues (2023)</strong> combined the <strong>framing effect</strong> (sure option for gains, risky option for losses) with the <strong>default effect</strong>, choosing the preselected option.", "A <strong>risky default raised risk taking</strong>, a sure default did <strong>not</strong> raise risk aversion, and the two effects were <strong>additive</strong>.", "In an <strong>exploratory</strong> question asked after the choice, the <strong>belief</strong> about the default's origin went with following or rejecting it."], "image": 16}, {"page": 18, "title": "Chein et al. (2011) and Albert, Chein & Steinberg (2013): Peers and the adolescent brain", "bullets": ["<strong>Albert, Chein and Steinberg (2013)</strong> argue adolescents reason about risk like adults in the lab, but the <strong>peer context</strong> is what raises risk taking.", "<strong>Chein and colleagues (2011)</strong> scanned a driving game played <strong>alone</strong> or <strong>watched by friends</strong>: adolescents took more risks when watched, with greater <strong>reward-region</strong> activity.", "<strong>Cognitive-control regions</strong> did not change with peers, so the authors concluded the effect worked mainly through <strong>reward circuitry</strong>."], "image": 17}], "original": ["media/collection15/lab-phonological-similarity.jpg", "media/collection15/lab-neighborhood-size.jpg", "media/collection15/lab-brown-peterson.jpg", "media/collection15/lab-modality-effect.png", "media/collection15/lab-partial-report.png", "media/collection15/lab-position-error.jpg", "media/collection15/lab-mental-rotation.jpg", "media/collection15/lab-typical-reasoning.jpg", "media/collection15/lab-wason-selection.jpg", "media/collection15/lab-decision-making.jpg", "media/collection15/lab-monty-hall.jpg", "media/collection15/lab-risky-decisions.jpg", "media/collection15/german-defeyter-2000-fig1.png", "media/collection15/leist-2022-fig1.png", "media/collection15/morrison-richmond-2020-fig1.png", "media/collection15/hoover-healy-2019-fig1.png", "media/collection15/giuliani-2023-fig1.png", "media/collection15/albert-2013-fig1.png"], "optional": false}, "questions": [{"id": 8001, "module": 14, "page": 1, "kind": "researcher", "stem": "People recalled lists of letters. Which result is found with lists of similar-sounding items, and what does it show about the code used in short-term memory?", "options": ["Lists of similar-sounding items were recalled worse than lists of different-sounding items, showing a speech-based code.", "Lists of similar-looking items were recalled worse than lists of different-looking items, showing a purely visual code.", "Lists of similar-sounding items were recalled better than lists of different-sounding items, showing sound helps recall.", "Lists of similar-sounding items and different-sounding items were recalled equally well, showing no code is used."], "correct": 0, "why": "Similar-sounding items are recalled worse, which is the phonological (acoustic) similarity effect. This points to a speech-based code. A visual code would predict look-alike confusions, not sound-alike ones, and the similarity cost is a cost, not a benefit or a null result."}, {"id": 8002, "module": 14, "page": 1, "kind": "design", "stem": "In an articulatory suppression condition, participants keep their speech machinery busy while they study lists. What was this manipulation designed to test?", "options": ["Whether blocking the conversion of visual input into a speech code would remove the similar-sounding cost.", "Whether people can remember more items when they speak aloud than when they stay silent.", "Whether visually similar letters are confused more often than acoustically similar letters.", "Whether the sensory store lasts longer when the articulatory machinery is occupied."], "correct": 0, "why": "Articulatory suppression keeps the articulatory control process busy so recoding into speech cannot happen. If the similarity effect depends on that recoding, it should vanish. The other options describe different questions (speaking aloud benefits, visual confusions, sensory store duration) that the manipulation was not built to address."}, {"id": 8003, "module": 14, "page": 1, "kind": "application", "stem": "A student silently looks at the letters B, D, G, P, T, V and then writes them from memory, making several errors. Which kind of error would the phonological similarity effect lead you to expect?", "options": ["Swapping letters that sound alike, such as writing B in place of D.", "Swapping letters that look alike, such as writing E in place of F.", "Forgetting the first letters of the list but remembering the final ones accurately.", "Remembering the letters perfectly because silent viewing avoids any speech code."], "correct": 0, "why": "These letters sound alike, and people recode silent visual input into a speech form, so sound-alike items get confused. Look-alike confusions would indicate a visual code, and silent viewing does not prevent recoding."}, {"id": 8004, "module": 14, "page": 2, "kind": "researcher", "stem": "Roodenrys et al. (2002) compared recall of words from large and small neighborhoods in a short-term memory task. What did Roodenrys et al. (2002) find?", "options": ["People recalled more large-neighborhood words than small-neighborhood words.", "People recalled more small-neighborhood words than large-neighborhood words.", "People recalled large- and small-neighborhood words equally well.", "People recalled large-neighborhood words better only when the words sounded alike."], "correct": 0, "why": "Roodenrys et al. (2002) found better recall for large-neighborhood words, showing that long-term memory factors influence short-term memory. Better recall for small neighborhoods, equal recall, or a sound-similarity condition do not match their result."}, {"id": 8005, "module": 14, "page": 2, "kind": "definition", "stem": "In memory research, a word's neighborhood can be defined in two ways. Which pair of definitions is correct?", "options": ["The words that differ from it by one letter (orthographic) or by one sound (phonological).", "The words that appear near it on a list (orthographic) or that rhyme with it (phonological).", "The words with the same meaning (orthographic) or the same first sound (phonological).", "The words that differ from it by one syllable (orthographic) or by one meaning (phonological)."], "correct": 0, "why": "A neighborhood is the set of words differing by one letter or one sound. List position, rhyme alone, shared meaning, and syllable-level differences are not how neighborhood is defined."}, {"id": 8006, "module": 14, "page": 2, "kind": "application", "stem": "A researcher wants to use memory span as a pure measure of how much a person's short-term memory can hold. According to the neighborhood size effect, what problem does this plan face?", "options": ["Span depends partly on long-term memory factors such as word neighborhood, so it is not a pure capacity measure.", "Span depends only on how fast people can speak, so it measures speech rate instead of capacity.", "Span is the same for every word list, so it cannot reveal individual differences.", "Span is determined entirely by the sensory store, so it measures perception rather than short-term memory."], "correct": 0, "why": "Because large-neighborhood words are recalled better, long-term memory influences span, so span is not purely short-term capacity. Speech rate only, identical spans, and sensory-store determination are not implied by the effect."}, {"id": 8007, "module": 14, "page": 3, "kind": "researcher", "stem": "In the Brown-Peterson task, counting backwards is very different from remembering letters. Which explanation of the forgetting did the researchers therefore judge unlikely?", "options": ["Interference from other material, rather than decay.", "Decay over time, rather than interference.", "A failure of attention, rather than interference.", "A failure of the sensory store, rather than decay."], "correct": 0, "why": "Counting backwards is so unlike remembering letters that interference seemed an unlikely cause, and the researchers concluded decay. The other options name explanations they did not set aside."}, {"id": 8008, "module": 14, "page": 3, "kind": "design", "stem": "In the Brown-Peterson task, participants do a distracting task such as counting between seeing the letters and recalling them. Why does counting suit the goal of testing decay?", "options": ["It blocks rehearsal, and because counting is so unlike remembering letters the researchers judged it an unlikely cause of interference.", "It strengthens the memory trace, because counting is similar to remembering letters.", "It adds new letters to memory, which creates interference between the letters.", "It keeps attention on the letters, so rehearsal continues during the delay."], "correct": 0, "why": "The distractor stops rehearsal, and since it is unlike the letters, the researchers judged interference an unlikely cause of any forgetting, which isolates decay. Strengthening, adding letters, or encouraging rehearsal would defeat that purpose."}, {"id": 8009, "module": 14, "page": 3, "kind": "application", "stem": "In a Brown-Peterson style study, recall gets worse the longer people are kept from rehearsing the letters. Which conclusion did Peterson and Peterson (1959) draw from this pattern?", "options": ["Short-term memory loses information through decay when rehearsal is blocked.", "Short-term memory keeps information indefinitely whether or not it is rehearsed.", "Short-term memory loses information only when similar letters appear on the list.", "Short-term memory is not involved in recalling letters after a delay."], "correct": 0, "why": "As the distraction gets longer, recall worsens, and Peterson and Peterson concluded that short-term memory loses information through decay unless it is rehearsed. This is the researchers' conclusion. Indefinite retention, similarity-only loss, and no involvement contradict the pattern."}, {"id": 8010, "module": 14, "page": 4, "kind": "definition", "stem": "What is the modality effect in memory for lists?", "options": ["Better memory for the last one or two items when a list is heard than when it is looked at silently.", "Better memory for the first one or two items when a list is looked at silently than when it is heard.", "Better memory for the middle items of a list when the list is heard rather than seen.", "Better memory for all items when a list is shown in the same sense as the test."], "correct": 0, "why": "The modality effect is an advantage for the final items of a heard list over a silently viewed one. The other options name the wrong items or the wrong direction."}, {"id": 8011, "module": 14, "page": 4, "kind": "researcher", "stem": "Which explanation of the modality effect do Neath and Surprenant (2003) offer?", "options": ["Hearing a list gives an extra type of information, how it sounds, which helps with the final items.", "Hearing a list makes people rehearse it faster, which helps with the first items.", "Hearing a list blocks the speech code, which helps with the middle items.", "Hearing a list removes the need for any memory store, which helps with all items."], "correct": 0, "why": "Neath and Surprenant (2003) argued that auditory presentation provides extra sound information that helps the final items. The other explanations propose rehearsal speed, blocked speech codes, or no store, none of which they gave."}, {"id": 8012, "module": 14, "page": 4, "kind": "definition", "stem": "The modality effect strongly influenced ideas about sensory memory. How is sensory memory characterized?", "options": ["A back-up store of raw, unanalyzed sensory input that can help recall when its information is useful.", "A permanent store of facts and meanings that supports recall after long delays.", "A rehearsal loop that converts visual input into a speech code.", "A store of well-analyzed information that is kept only for the most important items."], "correct": 0, "why": "Sensory memory holds raw, unanalyzed sensory input as a back-up. A permanent knowledge store, a rehearsal loop, and a store of analyzed items describe other systems."}, {"id": 8013, "module": 14, "page": 5, "kind": "researcher", "stem": "Earlier work suggested that people can report only a small part of a brief glance. What did Sperling (1960) argue about the cause of that limit?", "options": ["The limit came from recalling what was seen, not from perceiving it.", "The limit came from perceiving too little, because the glance was too short to register the items.", "The limit came from the display being unreadable, so the items never reached memory.", "The limit came from interference between the items during the glance itself."], "correct": 0, "why": "Sperling (1960) argued the limit reflected recall, since a cue right after the display allowed almost perfect report of the cued part, showing that nearly everything had been perceived. The other options place the limit in perception or the display."}, {"id": 8014, "module": 14, "page": 5, "kind": "design", "stem": "Why did Sperling (1960) ask participants to report only a cued part of the display, rather than the whole display?", "options": ["So the limit on how much can be recalled would not hide how much of the display was still available.", "So participants could rehearse the whole display before the cue arrived.", "So participants would report the entire display faster than before.", "So participants would pay attention only to the part they expected to be cued."], "correct": 0, "why": "Reporting only a cued part avoids the recall limit, so accuracy for that part estimates what was held from the whole display. The cue was not meant to allow rehearsal, speed up full report, or direct attention beforehand."}, {"id": 8015, "module": 14, "page": 5, "kind": "application", "stem": "In a partial report study, accuracy for the cued part is very high when the cue comes immediately but falls back to the usual low level when the cue is delayed. What does the drop show?", "options": ["The sensory (iconic) store holds a lot of information, but only very briefly.", "The sensory store holds only a few items, whatever the delay.", "The sensory store lasts a long time, so delays do not matter.", "The sensory store is created by the cue, so late cues cannot use it."], "correct": 0, "why": "High report with immediate cues shows a large store, and the fall with delay shows it lasts only briefly. A fixed small capacity, a long-lasting store, or a cue-created store do not fit."}, {"id": 8016, "module": 14, "page": 6, "kind": "definition", "stem": "What does the position error effect say about how people remember the order of items?", "options": ["Items are usually recalled in the correct position, and the errors that occur are systematic rather than random.", "Items are usually recalled in the wrong position, and the errors that occur are random.", "Items are recalled in the correct position only when the list is heard.", "Items are recalled in the correct position only when the list is short."], "correct": 0, "why": "The position error effect: order is usually right and errors are systematic. Mostly wrong, random errors, or a modality-only or length-only restriction are not what it states."}, {"id": 8017, "module": 14, "page": 6, "kind": "application", "stem": "A student studies seven words in order and recalls them, putting several words one place away from where they belong. Which description of the student's memory fits the position error effect?", "options": ["The student retains approximate position information for the words, so forgetting is not total loss.", "The student has lost the words completely, because misplaced words show information was erased.", "The student guessed the order at random, because misplaced words show no position information.", "The student relied only on a visual code, because misplaced words look alike."], "correct": 0, "why": "Systematic near-miss errors show approximate position information is retained. Complete loss, random guessing, and a visual-code explanation do not fit."}, {"id": 8018, "module": 14, "page": 6, "kind": "design", "stem": "Why can scoring recall only as percent correct give a misleading picture of forgetting order information?", "options": ["It treats a nearby wrong position as total loss, hiding that people still retain approximate position information.", "It treats a correct position as an error, hiding that people forget most items.", "It treats random guesses as correct, hiding that people retain no position information.", "It treats spoken items as written items, hiding the difference between sounds and meanings."], "correct": 0, "why": "A strict percent-correct score counts every misplaced item as wrong, even though errors are systematic and show retained approximate position. The other options misdescribe how the scoring works."}, {"id": 8019, "module": 14, "page": 7, "kind": "researcher", "stem": "Shepard and Metzler (1971) showed people two block shapes and asked whether they were the same or mirror images. What did their findings suggest about mental images?", "options": ["Mental images are much like real images, because rotating one takes time, as with a real object.", "Mental images are very different from real images, because they can be rotated instantly.", "Mental images are less reliable than descriptions, because people cannot rotate them.", "Mental images are stored only as words, because people describe the shapes aloud."], "correct": 0, "why": "Shepard and Metzler (1971) suggested that mental rotation takes time like real rotation, so mental images are much like real images. Instant rotation, no rotation, and word-only storage contradict this."}, {"id": 8020, "module": 14, "page": 7, "kind": "design", "stem": "In the task of Shepard and Metzler (1971), one block shape was turned relative to the other before people judged whether they were the same or mirror images. Why was one shape turned?", "options": ["So that deciding required rotating a mental image, letting researchers see how that rotation behaves.", "So that the shapes would look more different, making the judgment easier.", "So that people would use words instead of images to compare the shapes.", "So that people would rely on their own descriptions of their images."], "correct": 0, "why": "Turning one shape forces a mental rotation to compare them, revealing how mental imagery works. It does not make the task easier, encourage verbal strategies, or depend on self-description."}, {"id": 8021, "module": 14, "page": 7, "kind": "application", "stem": "Suppose you count the windows in your home by picturing it. Which conclusion about mental images fits the finding that they behave like real images?", "options": ["Mental images behave like real images, so tasks like this one can be done by inspecting an image.", "Mental images behave nothing like real images, so this task cannot involve imagery.", "Mental images can be trusted completely, because people's descriptions of them are accurate.", "Mental images are only a verbal list, so counting depends on words alone."], "correct": 0, "why": "Mental images behave like real images, so tasks such as counting windows can be done by inspecting an image. The other options deny that or claim images are verbal or perfectly trustworthy."}, {"id": 8022, "module": 14, "page": 8, "kind": "definition", "stem": "In judging probability, what are heuristics?", "options": ["Quick strategies that trade accuracy for speed and are usually good enough, but can produce wrong judgments.", "Careful calculations that trade speed for accuracy and are never wrong.", "Random guesses that ignore all information about the situation.", "Emotional reactions that replace judgment of probability altogether."], "correct": 0, "why": "Heuristics trade accuracy for speed, are usually adequate, but can yield wrong judgments. Careful calculation, random guesses, and emotion-only reactions are not heuristics in this sense."}, {"id": 8023, "module": 14, "page": 8, "kind": "application", "stem": "A person reads a short description of a quiet, bookish woman and says it is more likely that she is a librarian who also plays the violin than that she is a librarian. Which error is this?", "options": ["The conjunction fallacy, thinking that A and B together are more likely than A alone.", "The framing effect, giving a different answer because the options are worded differently.", "The phonological similarity effect, confusing items that sound alike.", "The modality effect, remembering heard items better than seen items."], "correct": 0, "why": "Rating a combination as more likely than one of its parts is the conjunction fallacy. The other options are different effects."}, {"id": 8024, "module": 14, "page": 8, "kind": "researcher", "stem": "Shafir, Smith, and Osherson (1990) had people read short descriptions of a person and rate how likely the person was to have certain professions or activities. What did they find?", "options": ["Sometimes people rated the combination of two professions or activities as more likely than one of its parts.", "People always rated the combination as less likely than each of its parts.", "People rated every profession or activity as equally likely.", "People refused to rate a combination because it could not be judged."], "correct": 0, "why": "Shafir, Smith, and Osherson (1990) found that in some cases the combination was rated more likely than a part, the conjunction fallacy. Always lower ratings, equal ratings, or refusal are not their finding."}, {"id": 8025, "module": 14, "page": 9, "kind": "definition", "stem": "In the Wason Selection Task with the rule 'If a card has a D on one side, it has a 3 on the other side,' which cards do people typically choose?", "options": ["D and 3, where the 3 can only confirm the rule and the 7, which could falsify it, is missed.", "D and 7, the cards that could show the rule is broken.", "Only the 7, since it is the only card that matters.", "All four cards, since any of them could break the rule."], "correct": 0, "why": "People typically pick D and 3, but the back of the 3 can only confirm the rule, while the 7 could falsify it. D and 7 is the correct pair, not the typical choice."}, {"id": 8026, "module": 14, "page": 9, "kind": "researcher", "stem": "Wason and Shapiro (1971) compared abstract rules with thematic rules. What did they find about when people can test a rule well?", "options": ["People can test a rule when they have relevant experience, as with a familiar thematic rule.", "People can test a rule only when it is abstract and free of everyday content.", "People can test a rule equally well regardless of its content or their experience.", "People can test a rule only when they are told which cards to turn over."], "correct": 0, "why": "Wason and Shapiro (1971) found that familiar thematic rules are easier because experience helps. Abstract-only, content-independent, and instruction-dependent claims do not fit."}, {"id": 8027, "module": 14, "page": 9, "kind": "application", "stem": "Two groups test rules with the same logic. One group tests 'If you borrow my car, you must fill up the gas tank,' and the other tests 'If a card has a D on one side, it has a 3 on the other side.' Which group should do better, and why?", "options": ["The car group, because familiar content draws on relevant experience.", "The card group, because abstract content invites falsification.", "Neither group, because the logic is identical so performance must match.", "The card group, because familiar content makes people look only for confirmation."], "correct": 0, "why": "Thematic rules are much easier than abstract rules because people can use relevant experience. Identical logic does not guarantee identical performance."}, {"id": 8028, "module": 14, "page": 10, "kind": "definition", "stem": "What is a framing effect?", "options": ["A case in which the wording or context makes a big difference even when the situations are otherwise equivalent.", "A case in which people choose the option with the best outcome regardless of how it is worded.", "A case in which people forget a choice because it was worded in an unfamiliar way.", "A case in which people change their choice only because the options themselves differ."], "correct": 0, "why": "In a framing effect, wording or context changes choices even though the situations are otherwise equivalent. Wording-independent choice, forgetting, and changes caused by real option differences do not define it."}, {"id": 8029, "module": 14, "page": 10, "kind": "design", "stem": "Researchers studying framing present the same choice in two different ways. Why is it important that the two versions are otherwise equivalent?", "options": ["So any difference in choices can be attributed to the wording or context rather than to the options.", "So participants will not notice that they are being tested on their decisions.", "So participants will choose the better outcome in both versions.", "So the outcomes can be made to differ while the wording stays the same."], "correct": 0, "why": "If the situations are equivalent, a difference in choice can only come from the framing. The other options misstate the purpose."}, {"id": 8030, "module": 14, "page": 10, "kind": "application", "stem": "A company announces a plan to 'save 200 of 600 jobs' to one group and a plan that 'will lose 400 of 600 jobs' to another group, and the two groups choose differently. What does this illustrate?", "options": ["A framing effect, because equivalent outcomes were worded differently and choices changed.", "A modality effect, because one group heard the plan and the other saw it.", "A conjunction fallacy, because the plans combined two outcomes.", "A neighborhood size effect, because the plans used similar words."], "correct": 0, "why": "The two plans describe equivalent outcomes with different wording, and the choice changed: a framing effect. The other options name unrelated effects."}, {"id": 8031, "module": 14, "page": 11, "kind": "application", "stem": "In the Monty Hall 3 Door problem, you pick one door, and Monty Hall, who always plays fair this way, opens another door to show no prize. What should you do?", "options": ["Switch to the other closed door, because switching wins about two-thirds of the time.", "Stay with your door, because staying wins about two-thirds of the time.", "Choose at random, because the two remaining doors are equally likely.", "Switch only if your first pick was the door on the left."], "correct": 0, "why": "Your first pick has a 1 in 3 chance, so the other two doors together hold 2 in 3, and the opened door shows no prize, leaving all of that on the other closed door. Staying wins about one-third and random choice about half."}, {"id": 8032, "module": 14, "page": 11, "kind": "application", "stem": "In the Monty Hall 3 Door problem, why do many people wrongly think that staying and switching are equally good?", "options": ["They treat the two remaining doors as equally likely, ignoring that the first pick keeps its original chance.", "They believe the host moves the prize after the contestant chooses.", "They believe the first pick is certain to be correct once a door is opened.", "They believe the host opens doors at random, including the prize door."], "correct": 0, "why": "People see two closed doors and call it even, but the first pick still has only a one in three chance, so the other closed door holds the rest. The other options are not the usual mistake."}, {"id": 8033, "module": 14, "page": 12, "kind": "definition", "stem": "In research on choices between a sure outcome and a gamble, what pattern do people typically show?", "options": ["They avoid risk with gains by taking the sure thing, and seek risk with losses by taking the gamble.", "They seek risk with gains by taking the gamble, and avoid risk with losses by taking the sure thing.", "They avoid risk with both gains and losses by always taking the sure thing.", "They seek risk with both gains and losses by always taking the gamble."], "correct": 0, "why": "In prospect-theory research, people typically avoid risk with gains and seek risk with losses. The other patterns reverse or flatten it."}, {"id": 8034, "module": 14, "page": 12, "kind": "application", "stem": "A person is offered a sure gain or a gamble that could win more but might win nothing, with the same average payoff. Based on the typical pattern, which is the person most likely to choose?", "options": ["The sure gain, because people usually avoid risk with gains.", "The gamble, because people usually seek risk with gains.", "The gamble, because people usually prefer the larger possible win whatever the odds.", "Either at random, because the pattern does not apply when the average payoff is equal."], "correct": 0, "why": "People typically take the sure thing for gains. Seeking risk is the typical pattern for losses, not gains."}, {"id": 8035, "module": 14, "page": 13, "kind": "researcher", "stem": "German and Defeyter (2000) had children use an overturned box as a support so that a toy bear could reach a toy on a high shelf, after first seeing the box used as a container in one condition. What did they find about the youngest children?", "options": ["Five-year-olds were not slowed by having seen the container use and were even faster than older children in that condition.", "Five-year-olds were slowed the most by having seen the container use, more than the older children.", "All age groups were equally slowed by having seen the container use, so age made no difference.", "Five-year-olds could not solve the task at all, while older children solved it quickly after the container use."], "correct": 0, "why": "German and Defeyter (2000) found that 6- and 7-year-olds were slower after the container use was shown, while 5-year-olds were immune and were faster than the older children. The distractors reverse or erase this age contrast."}, {"id": 8036, "module": 14, "page": 13, "kind": "definition", "stem": "A child who has just watched a cup used to hold pencils cannot think of turning that same cup upside down to serve as a step stool. Which concept does this illustrate?", "options": ["Functional fixedness, being stuck on an object's usual function and failing to see another use.", "Perseveration, repeating a previous response even after the situation has changed.", "Mental set, applying a familiar solution method to a problem that needs a different approach.", "Insight, suddenly seeing the whole solution after a period of impasse."], "correct": 0, "why": "Functional fixedness is being stuck on an object's usual function. The other terms name different problem-solving phenomena."}, {"id": 8037, "module": 14, "page": 13, "kind": "design", "stem": "In the box task, German and Defeyter (2000) included a condition where children first saw the box used as a container and a condition where they did not. What did comparing these conditions allow them to separate?", "options": ["The effect of having seen the box's usual container function from ordinary improvement in problem solving with age.", "The effect of the toy bear's appearance from the effect of the shelf's height.", "The effect of children's memory for the room from their motivation to please the experimenter.", "The effect of adults' training from the effect of children's natural curiosity."], "correct": 0, "why": "Without the container demonstration children simply improved with age, so the contrast shows what the demonstration itself added: a slowing in the older children. The distractors name variables that the condition does not manipulate."}, {"id": 8038, "module": 14, "page": 14, "kind": "researcher", "stem": "Leist and colleagues (2022) tested children and adults on memory for the order of verbal items and of spatial items while speech was played that they were to ignore. What did they find?", "options": ["Speech impaired recall of verbal items but did not disrupt recall of spatial items in either age group.", "Speech impaired recall of verbal and spatial items equally in both children and adults.", "Speech impaired recall of spatial items more than verbal items, especially in adults.", "Speech impaired recall only in adults, while children were unaffected for both kinds of items."], "correct": 0, "why": "Leist and colleagues (2022) found the irrelevant speech effect to be specific to verbal material; neither group was disrupted on the spatial task. The option claiming equal effects on verbal and spatial items is not what was found."}, {"id": 8039, "module": 14, "page": 14, "kind": "definition", "stem": "In studies of the irrelevant speech effect, speech made of different syllables is compared with one syllable repeated over and over. What is the first kind of speech called, and what is its effect?", "options": ["Changing-state speech, which impairs serial recall more than steady-state speech does.", "Steady-state speech, which impairs serial recall more than changing speech does.", "Changing-state speech, which improves serial recall by helping rehearsal of the list.", "Phonological speech, which impairs serial recall only when it is attended to."], "correct": 0, "why": "Changing-state speech (different syllables) impairs serial recall more than steady-state speech (one syllable repeated). The distractors swap the labels or invert the effect."}, {"id": 8040, "module": 14, "page": 14, "kind": "design", "stem": "Why did Leist and colleagues (2022) test memory for spatial items as well as verbal items?", "options": ["Because explanations based on order rehearsal or attention capture predict disruption for any item, while a verbal-specific account predicts disruption only for verbal items.", "Because spatial items are easier to remember, which lets the speech effect be measured more precisely.", "Because children are known to perform better on spatial than on verbal tasks at every age.", "Because spatial items allow the speech to be left out of the task without changing anything else."], "correct": 0, "why": "Changing-state and attention-capture accounts predict spatial disruption too, whereas similarity-based interference with phonological representations predicts verbal-only disruption. Spatial items therefore separate these accounts; the distractors give reasons unrelated to the theories."}, {"id": 8041, "module": 14, "page": 15, "kind": "definition", "stem": "A student lists the items to buy in a notebook rather than trying to hold them in mind, to reduce the mental demands of the shopping trip. What is this action called?", "options": ["Cognitive offloading, using actions such as writing things down to reduce the mental demands of a task.", "Chunking, grouping separate items into larger meaningful chunks to hold more in mind.", "Maintenance rehearsal, repeating items silently to keep them active in memory.", "Elaborative encoding, linking new items to existing knowledge to deepen processing."], "correct": 0, "why": "Cognitive offloading is using actions like writing things down to reduce the mental demands of a task. The distractors are other memory strategies that keep the load in the mind."}, {"id": 8042, "module": 14, "page": 15, "kind": "researcher", "stem": "Morrison and Richmond (2020) had people remember lists of letters of different lengths, sometimes with pen and paper available and sometimes with memory only. What did they find about offloading?", "options": ["Offloading improved memory, especially at higher loads, and people offloaded more as the load grew.", "Offloading improved memory equally at all loads, and people offloaded at the same rate regardless of load.", "Offloading lowered memory at high loads, so people offloaded less as the load grew.", "Offloading helped only at very small loads, and people offloaded most when the list was short."], "correct": 0, "why": "Morrison and Richmond (2020) found that offloading helped most at higher loads and that people offloaded more as the load grew. The distractors flip the load pattern."}, {"id": 8043, "module": 14, "page": 15, "kind": "application", "stem": "A researcher expects that people with weaker working memory will write things down more often than people with stronger working memory. Which result did Morrison and Richmond (2020) obtain on this point?", "options": ["Memory ability did not predict who offloaded or who benefited, suggesting offloading may help people across abilities.", "People with weaker memory offloaded much more often and gained far more.", "People with stronger memory offloaded more often because they could plan better how to use the notepad.", "Offloading helped only the people with the strongest memory, since weaker people made errors when writing."], "correct": 0, "why": "Morrison and Richmond (2020) found no link between memory ability and offloading, and capacity did not predict the benefit, so offloading may help across abilities. The distractors assert a link that was not found."}, {"id": 8044, "module": 14, "page": 16, "kind": "definition", "stem": "According to one account, wrong answers on the bat-and-ball problem come from reasoners neglecting the phrase 'more than' and answering an easier question without noticing. What is this process called?", "options": ["Unconscious attribute substitution, swapping an easier problem in for the harder one that was asked.", "Confirmation bias, searching only for information that supports a belief already held.", "Functional fixedness, being stuck on an object's usual function and missing a new use.", "Anchoring, relying too heavily on the first number encountered when estimating."], "correct": 0, "why": "That account proposes unconscious attribute substitution, in which reasoners swap in an easier problem. The other labels are different biases."}, {"id": 8045, "module": 14, "page": 16, "kind": "researcher", "stem": "Hoover and Healy (2019) tested people who gave the intuitive wrong answer to the bat-and-ball problem. What did they find about the phrase 'more than'?", "options": ["Most incorrect reasoners could recall and recognize the phrase, so it was not simply overlooked, but they apparently did not use its meaning.", "Most incorrect reasoners failed to notice the phrase at all, which confirms that it was overlooked.", "Most incorrect reasoners understood the phrase fully but chose the wrong answer to be quick.", "Most incorrect reasoners recalled the phrase only when told that their answer was wrong."], "correct": 0, "why": "Hoover and Healy (2019) found stronger evidence for a conscious error process: the phrase was processed but its meaning apparently was not used. The distractors say it was overlooked or fully understood."}, {"id": 8046, "module": 14, "page": 16, "kind": "design", "stem": "Researchers compared the standard bat-and-ball problem with a control version that lacks the words 'more than'. What did this control version allow them to show?", "options": ["That incorrect reasoners were less confident on the standard problem than on the control, suggesting they sensed something was off.", "That incorrect reasoners were more confident on the standard problem than on the control, suggesting they felt sure.", "That all reasoners solved the control correctly, which proves the standard version is unfair.", "That the words 'more than' make the problem take longer to read but change nothing else."], "correct": 0, "why": "Incorrect reasoners were less confident on the standard problem than on the control without 'more than', which is called substitution sensitivity. The control isolates the effect of the phrase."}, {"id": 8047, "module": 14, "page": 17, "kind": "researcher", "stem": "Giuliani and colleagues (2023) gave people life-or-death and financial choices with no default, a sure default, or a risky default. What did they find about defaults?", "options": ["A risky default raised risk taking, while a sure default did not increase risk aversion.", "A sure default raised risk aversion, while a risky default did not increase risk taking.", "Both defaults pushed people equally toward the option that was preselected.", "Defaults had no effect once people were given life-or-death wording."], "correct": 0, "why": "Giuliani and colleagues (2023) found that a risky default raised risk taking while a sure default did not raise risk aversion overall, so in some circumstances people can be nudged toward risk more easily than toward certainty. Framing and default had additive, independent effects."}, {"id": 8048, "module": 14, "page": 17, "kind": "application", "stem": "In the research of Giuliani and colleagues (2023), people were asked afterward why they thought an option had been preselected. Which belief went with rejecting the default most often?", "options": ["Thinking the default came from previous respondents or from chance.", "Thinking the default was the most rational choice.", "Thinking the default was a mistake in the survey.", "Thinking the default was the safest and surest option."], "correct": 0, "why": "In this exploratory, after-the-choice question, Giuliani and colleagues (2023) found that people who thought the default came from previous respondents or chance tended to reject it most often, while those who saw it as the most rational choice followed it most. The other options describe beliefs that went with following or with nothing reported."}, {"id": 8049, "module": 14, "page": 18, "kind": "researcher", "stem": "Chein and colleagues (2011) scanned people playing a driving game alone or watched by friends in another room. What did they find in adolescents when friends were watching?", "options": ["Reward-related regions, the ventral striatum and orbitofrontal cortex, were more active, and this went with risky decisions.", "Cognitive-control regions were much less active when friends watched than when alone, which explained the risky decisions.", "Reward-related regions were less active, which explained why adolescents took fewer risks.", "No brain region changed, so the extra risk taking was due to overt peer pressure."], "correct": 0, "why": "Chein and colleagues (2011) concluded the peer effect worked mainly through enhanced reward-circuit activity; cognitive-control regions did not change with peers, and friends were in another room, so it was not overt peer pressure."}, {"id": 8050, "module": 14, "page": 18, "kind": "design", "stem": "Why did Chein and colleagues (2011) have participants play the driving game alone and also with friends watching from another room?", "options": ["To compare friends watching without interacting during play against an alone baseline, so peer presence could be separated from overt peer pressure.", "To separate the effect of practice from the effect of fatigue by repeating the game twice.", "To separate the effect of friendship from the effect of the difficulty of the driving game.", "To separate the effect of age by testing the same people at two different ages."], "correct": 0, "why": "Friends watching from another room, with no interaction during the task, is a peer context without overt pressure, so the alone baseline shows what the peer context adds. The distractors name variables the design does not isolate."}], "revision": "articles-labs-balanced-100", "lectureNumber": "15", "topics": [{"module": 14, "title": "Phonological Similarity Effect", "pages": [1], "progressKey": "m2-topic-14-1"}, {"module": 14, "title": "Neighborhood Size Effect", "pages": [2], "progressKey": "m2-topic-14-2"}, {"module": 14, "title": "Brown-Peterson Task", "pages": [3], "progressKey": "m2-topic-14-3"}, {"module": 14, "title": "Modality Effect", "pages": [4], "progressKey": "m2-topic-14-4"}, {"module": 14, "title": "Partial Report", "pages": [5], "progressKey": "m2-topic-14-5"}, {"module": 14, "title": "Position Error Effect", "pages": [6], "progressKey": "m2-topic-14-6"}, {"module": 14, "title": "Mental Rotation", "pages": [7], "progressKey": "m2-topic-14-7"}, {"module": 14, "title": "Typical Reasoning", "pages": [8], "progressKey": "m2-topic-14-8"}, {"module": 14, "title": "Wason Selection", "pages": [9], "progressKey": "m2-topic-14-9"}, {"module": 14, "title": "Decision Making", "pages": [10], "progressKey": "m2-topic-14-10"}, {"module": 14, "title": "Monty Hall", "pages": [11], "progressKey": "m2-topic-14-11"}, {"module": 14, "title": "Risky Decisions", "pages": [12], "progressKey": "m2-topic-14-12"}, {"module": 14, "title": "German & Defeyter (2000): Immunity to functional fixedness in young children", "pages": [13], "progressKey": "m2-topic-14-13"}, {"module": 14, "title": "Leist et al. (2022): Irrelevant speech impairs serial recall of verbal but not spatial items", "pages": [14], "progressKey": "m2-topic-14-14"}, {"module": 14, "title": "Morrison & Richmond (2020): Offloading items from memory", "pages": [15], "progressKey": "m2-topic-14-15"}, {"module": 14, "title": "Hoover & Healy (2019): The Bat-and-Ball Problem", "pages": [16], "progressKey": "m2-topic-14-16"}, {"module": 14, "title": "Giuliani et al. (2023): The joint effect of framing and defaults on choice behavior", "pages": [17], "progressKey": "m2-topic-14-17"}, {"module": 14, "title": "Chein et al. (2011) and Albert, Chein & Steinberg (2013): Peers and the adolescent brain", "pages": [18], "progressKey": "m2-topic-14-18"}], "experiments": [{"module": 14, "title": "Phonological Similarity Effect", "pages": [1]}, {"module": 14, "title": "Neighborhood Size Effect", "pages": [2]}, {"module": 14, "title": "Brown-Peterson Task", "pages": [3]}, {"module": 14, "title": "Modality Effect", "pages": [4]}, {"module": 14, "title": "Partial Report", "pages": [5]}, {"module": 14, "title": "Position Error Effect", "pages": [6]}, {"module": 14, "title": "Mental Rotation", "pages": [7]}, {"module": 14, "title": "Typical Reasoning", "pages": [8]}, {"module": 14, "title": "Wason Selection", "pages": [9]}, {"module": 14, "title": "Decision Making", "pages": [10]}, {"module": 14, "title": "Monty Hall", "pages": [11]}, {"module": 14, "title": "Risky Decisions", "pages": [12]}, {"module": 14, "title": "German & Defeyter (2000): Immunity to functional fixedness in young children", "pages": [13]}, {"module": 14, "title": "Leist et al. (2022): Irrelevant speech impairs serial recall of verbal but not spatial items", "pages": [14]}, {"module": 14, "title": "Morrison & Richmond (2020): Offloading items from memory", "pages": [15]}, {"module": 14, "title": "Hoover & Healy (2019): The Bat-and-Ball Problem", "pages": [16]}, {"module": 14, "title": "Giuliani et al. (2023): The joint effect of framing and defaults on choice behavior", "pages": [17]}, {"module": 14, "title": "Chein et al. (2011) and Albert, Chein & Steinberg (2013): Peers and the adolescent brain", "pages": [18]}], "coreReview": [{"module": 14, "title": "Short-term and sensory memory labs", "pages": [1, 2, 3, 4, 5, 6]}, {"module": 14, "title": "Mental imagery and reasoning labs", "pages": [7, 8, 9]}, {"module": 14, "title": "Decision-making labs", "pages": [10, 11, 12]}, {"module": 14, "title": "Assigned articles", "pages": [13, 14, 15, 16, 17, 18]}]};
window.C15_TEXT = {"20": {"1": [{"text": "The **phonological similarity effect** is the finding that people recall a list **worse when its items sound alike** than when they sound different. What matters is how the items sound to each other, which is why **acoustic similarity effect** is arguably the better name.", "children": ["The surprising part is that it still happens when you **read the items silently**, with no sound at all.", "Conrad (1964) reported the effect."]}, {"text": "Because silent reading still produces it, we must be **recoding visual information into a speech-based form**. If memory used only a visual code, we would confuse items that **look** alike, such as E and F, rather than items that **sound** alike.", "children": ["This recoding idea is central to Baddeley's (1986) **phonological loop**, a component of **working memory**."]}, {"text": "The loop has two parts: a **phonological store** that briefly holds speech-based traces, and an **articulatory control process** that turns visual input into a speech code and refreshes the traces.", "children": ["Murray (1968) used **articulatory suppression**, in which the control process is kept busy, so visual items cannot be recoded.", "With recoding blocked, the loop predicts that similar-sounding and different-sounding visually presented lists are **recalled equally well**."]}], "2": [{"text": "The **neighborhood size effect** is a case where **long-term memory factors change short-term memory**. A word's neighborhood is every word you get by changing one letter (**orthographic**) or one sound (**phonological**).", "children": ["Cat has lots of neighbors, such as bat, cot and can, so it is a **large neighborhood word**; hippopotamus has none, so it is a **small neighborhood word**."]}, {"text": "Roodenrys et al. (2002) found that in a standard short-term memory task people **recall more large neighborhood words than small neighborhood words**.", "children": ["So what you know about the language, stored in long-term memory, changes performance on a short-term task."]}, {"text": "That causes trouble for **memory span**. If span is affected by long-term memory, it **cannot be a pure measure of short-term memory capacity**.", "children": []}], "3": [{"text": "The **Brown-Peterson task** was used to show that **information in short-term memory is forgotten quickly when rehearsal is prevented**. After McGeoch's (1932) influential critique, forgetting had been put down to **interference** and not decay.", "children": ["Peterson and Peterson (1959) had people see a few consonants and then do a hard **distractor task**, counting backwards, so they could not rehearse the letters."]}, {"text": "The longer the distractor lasted, the **less likely people were to recall the letters**.", "children": ["Counting backwards is very different from remembering letters, so Peterson and Peterson judged interference an unlikely explanation."]}, {"text": "Their conclusion was that there is a **short-term memory (STM) system** that holds information only briefly, and that without rehearsal the information **fades away (decay)**.", "children": ["That is their claim; Keppel and Underwood (1962) are cited as offering an alternative explanation of the results."]}], "4": [{"text": "The **modality effect** is an advantage for the **last one or two items** of a list when the list is **heard** rather than read silently.", "children": ["It also appears for lists that are **lip-read or silently mouthed**, so it is not only about hearing."]}, {"text": "These findings had a big influence on the idea of **sensory memory**, a system supposed to hold **raw, unanalyzed sensory input** as a back-up that can improve recall when its information is useful.", "children": []}, {"text": "The favored explanation, from Neath and Surprenant (2003), is that **auditory presentation provides an additional type of information** compared with visual presentation.", "children": ["When recalling the last items, you do better if you also have information about **how the list sounded**."]}], "5": [{"text": "Early researchers studying the **perceptual span** found that people could report only a small part of a brief glance, and this limit was built into many theories. Sperling (1960) suggested it came from **observers' ability to recall** what they had seen, not from perception.", "children": ["He used the **partial-report** method, where a cue after the display tells observers which part to report."]}, {"text": "When the cue came **right after the display disappeared**, observers reported the cued part almost perfectly, whichever part it was.", "children": ["So a **sensory (iconic) store** briefly held nearly a complete copy of the display."]}, {"text": "The real limit is the **time needed to report**, because the store fades while observers are reporting.", "children": ["When the cue was **delayed**, performance fell back toward the usual limit, which shows how **briefly** the store lasts."]}], "6": [{"text": "The **position error effect** is about remembering **order** as well as items, such as the digits of a phone number. Most of the time an item is **recalled in its correct position**.", "children": ["When a mistake is made, it is **systematic and predictable**, not random."]}, {"text": "A misplaced item most likely comes out in an **adjacent position**. An item that is not recalled third is probably recalled second or fourth, and rarely far from where it belongs.", "children": []}, {"text": "This matters because **percent correct alone makes forgetting look like lost information**. In fact people still remember **roughly where the item belonged**.", "children": []}], "7": [{"text": "The main theme is that **mental images behave like real images**. When we count the windows in our home, we seem to move through a **mental image**, but asking people to describe their images does not tell us much, since we cannot tell whether the images differ or only the descriptions do.", "children": ["So researchers use **tasks that require imagery** and change one critical part of the task, which lets them work out objectively what images are like."]}, {"text": "**Shepard and Metzler (1971)** showed people two unfamiliar block shapes and asked whether they were the **same shape or mirror images**, with one shape turned relative to the other. People said they **mentally rotated** one shape until it lined up with the other.", "children": ["The **more one shape was turned away from the other, the longer people took** to respond.", "That extra time grew at a steady, **constant rate**, as if the image turned at a fixed speed."]}, {"text": "So **rotating a mental image takes time**, just as turning a real object does, which suggests **mental images are much like real images**.", "children": ["These findings had a large influence on **theories of mental representation**."]}], "8": [{"text": "The main theme is that people judge probability with **heuristics**, which **trade some accuracy for speed**. Heuristics are usually good enough for day-to-day purposes, but they can lead to **incorrect judgments**.", "children": ["**Tversky and Kahneman (1983)** showed that people's estimates of probability often differ greatly from objective probabilities."]}, {"text": "A striking example is the **conjunction fallacy**, thinking that **both A and B together are more likely than A alone or B alone**.", "children": ["By objective probability, two events together can **never be more likely than** either one on its own, yet people sometimes judge otherwise."]}, {"text": "**Shafir, Smith, and Osherson (1990)** gave people short descriptions of a person and asked how likely it was that the person had certain professions or took part in certain activities. People sometimes rated the **combination as more likely than one part of it**.", "children": ["This supports the idea that people rely on **heuristics** rather than the rules of probability."]}], "9": [{"text": "People find it hard to test an **abstract rule**. In the **Wason Selection Task**, the rule is \"If a card has a D on one side, it has a 3 on the other side,\" and the job is to choose the cards that could show the rule is broken.", "children": ["The correct cards are **D and 7**, because a D without a 3, or a 7 with a D behind it, would **falsify** the rule.", "Most people pick D and 3, but the 3 card can only **confirm** the rule, since the rule says nothing about what must be behind a 3."]}, {"text": "A rule with the same logical form but familiar content, such as \"If you borrow my car, you must fill up the gas tank,\" is **much easier**.", "children": ["The right cards are **\"borrowed car\" and \"empty gas tank,\"** because those could reveal someone who borrowed the car and did not fill it."]}, {"text": "**Wason and Shapiro (1971)** compared abstract and thematic rules. People can test a rule when they have **knowledge or experience** that fits it.", "children": ["With thematic rules people use **experience, not logic per se**; with abstract rules they must rely **solely on logic**."]}], "10": [{"text": "The main theme is that **decisions are shaped by how a choice is framed**, not only by what the options are. People would like to weigh their options carefully, but many tendencies, called **framing effects**, push them in particular directions.", "children": ["It is fairly easy to create a context in which people choose a particular option."]}, {"text": "In a **framing effect**, the **perceived context or wording of the choice** makes a big difference, even when the situations are **otherwise equivalent**.", "children": ["**Kahneman and Tversky (1982)** summarized many framing effects."]}, {"text": "The same choice can be presented in **two different ways**, and people choose differently depending on the version.", "children": ["In classic framing research (Tversky and Kahneman), **gain wording** typically pushes people toward the **sure option** and **loss wording** toward the **gamble**, so the choice follows the framing and not the substance."]}], "11": [{"text": "The main theme is that **intuition about probability is often wrong**, and the **Monty Hall 3 Door problem** is the classic example. A prize is behind one of three doors, you pick one, and Monty Hall, who is assumed to play fair and always do this, opens one of the other two doors to show **no prize**. Should you **stay or switch**?", "children": ["Many people think it does not matter, which is **incorrect**."]}, {"text": "**The right choice is to switch.** Always switching wins about **two-thirds** of the time and always staying wins about **one-third**.", "children": ["Most people miss this because they treat the two remaining doors as equally likely."]}, {"text": "Your first pick has a **1 in 3 chance** of being right, so there is a **2 in 3 chance** the prize is behind one of the other two doors.", "children": ["When Monty Hall shows one of those doors is empty, that whole **2 in 3 chance moves to the remaining door**, while your own door stays at 1 in 3."]}], "12": [{"text": "The main theme is that **risky choices depend on framing**: the way a choice is framed makes a big difference to the decision, even when the situations are **otherwise equivalent**.", "children": ["**Kahneman and Tversky (1982)** summarized many of these **framing effects**."]}, {"text": "In this research people choose between a **guaranteed outcome** and a **gamble** with a stated chance of winning and a stated chance of losing.", "children": ["The guaranteed outcome can be a gain or a loss, so researchers can see how **risk, stakes, and gain versus loss** affect the choice."]}, {"text": "In prospect-theory research (Kahneman and Tversky), people typically **avoid risk when the choice is about gains**, taking the sure thing, and **seek risk when the choice is about losses**, taking the gamble.", "children": ["So risky decisions depend on how outcomes are **perceived**, not just on the objective odds."]}], "13": [{"text": "**German and Defeyter (2000)** asked whether young children show **functional fixedness**, being stuck on an object's **usual function** so that a new use is slow or missed.", "children": ["**Duncker's (1945) candle problem** is the classic case: the tack box is hard to see as a platform once it has held the tacks.", "Adults show it too (**Adamson, 1952**) and problem solving normally improves with age, so younger children were expected to do worse.", "In the box task, a toy bear wanted to reach a toy on a high shelf, and the solution was to turn a box over as a support; in one condition the box had first been used as a container."]}, {"text": "**Older children (6 and 7) were slower** to use the box as a support once its container use had been shown, while **5-year-olds were immune** and were even faster than the older children in that condition.", "children": ["Without the container demonstration, children simply got better with age."]}, {"text": "The authors, drawing on **German and Johnson (1997)**, predicted this: **younger children have a more fluid idea of function**, where any goal of the user can make an object's function.", "children": ["Older children hold function more rigidly, so the demonstrated container use has to be **restructured** before the box can become a support."]}], "14": [{"text": "The **irrelevant speech effect** is that speech you are told to ignore **impairs serial recall**, and **changing-state speech** (different syllables) hurts more than **steady-state speech** (one syllable repeated).", "children": ["Accounts differ: speech corrupts **phonological traces** (**Salamé and Baddeley, 1982**), changing sound disrupts **order rehearsal** for any item (**Jones and colleagues**), or sound **captures attention** (**Cowan, 1995**).", "**Leist and colleagues (2022)** separated these by testing **verbal** and **spatial** items in children and adults."]}, {"text": "Speech **impaired verbal recall but not spatial recall**, in both children and adults.", "children": ["Children were more impaired than adults relative to silence, and they were hurt by steady-state speech too, which adults were not.", "This did not reproduce **Jones and colleagues' (1995)** report of equal effects on verbal and spatial items."]}, {"text": "So the effect is **specific to verbal material**.", "children": ["That is hard for **attention-capture** and **changing-state** accounts, which predict spatial disruption too.", "It fits **similarity-based interference** between the speech and **phonological representations** of the list."]}], "15": [{"text": "**Cognitive offloading** is using actions such as writing things down to **reduce the mental demands** of a task (**Risko and Gilbert, 2016**).", "children": ["**Morrison and Richmond (2020)** replicated and extended **Risko and Dunn (2015)**, asking who offloads and whether it helps.", "They expected people with **lower working memory capacity** to offload more."]}, {"text": "**Offloading improved memory**, especially at **high loads** beyond short-term memory capacity, and people **offloaded more as the load grew**, as in Risko and Dunn.", "children": []}, {"text": "**Memory ability did not predict who offloaded**, which failed to replicate Risko and Dunn, and capacity did not predict the benefit either.", "children": ["So offloading **may be a compensatory strategy** that helps across a wide range of memory ability."]}], "16": [{"text": "In the **bat-and-ball problem** (**Frederick, 2005**), a bat and ball cost $1.10 together and the bat costs $1.00 more than the ball.", "children": ["The intuitive answer is **10 cents**, but then the bat is only 90 cents more.", "The correct answer is **5 cents**: ball x, bat x plus $1.00, so x is 5 cents."]}, {"text": "**Kahneman and Frederick (2002)** explained the error as **unconscious attribute substitution**: reasoners neglect 'more than' and answer an easier question.", "children": ["**De Neys, Rossi and Houdé (2013)** found incorrect reasoners were **less confident** on the standard problem than on a control without 'more than', called **substitution sensitivity**."]}, {"text": "**Hoover and Healy (2019)**, using matching problems, found that incorrect reasoners mostly **recalled and recognized 'more than'**, so it was not simply overlooked, but they apparently did not use its meaning.", "children": ["Some reasoners did lose the phrase and many stayed very confident, so substitution may still occur for some.", "Because they cannot be sure the error was substitution, they prefer the term **error sensitivity**."]}], "17": [{"text": "**Giuliani and colleagues (2023)** combined the **framing effect** (**Tversky and Kahneman, 1981**), where people prefer the **sure option for gains** and the **risky option for losses**, with the **default effect** (**Johnson and Goldstein, 2003**), a tendency to take the **preselected option**.", "children": ["The Asian disease problem is the classic example: 'saved' wording favors the sure program and 'die' wording favors the risky one.", "The two effects had mostly been studied separately."]}, {"text": "People made **life-or-death** and **financial** choices with **no default**, a **sure default**, or a **risky default**.", "children": ["They found a **classic framing effect** and **more risk taking when lives were at stake**, although lives concerned people elsewhere while the money was the participant's own, so involvement differed.", "A **risky default raised risk taking**, a **sure default did not raise risk aversion**, and framing and default were **additive**."]}, {"text": "Afterward people said why they thought the option was preselected. Those who saw it as the **most rational choice** followed it most, **expert advice** left people indifferent, and **previous respondents or chance** went with rejecting it.", "children": ["This question was exploratory and came after the choice, so beliefs may partly justify a choice already made."]}], "18": [{"text": "**Albert, Chein and Steinberg (2013)** reviewed why adolescents take more risks in real life although they **reason about risk as well as adults in the lab**.", "children": ["Their answer is the **peer context**, shown by **Gardner and Steinberg (2005)**, where adolescents took more risks with peers present than alone and adults did not.", "Peers prime the **reward system** (ventral striatum, orbitofrontal cortex) while the **cognitive-control system** (lateral prefrontal cortex) matures slowly, a **maturational gap**."]}, {"text": "**Chein and colleagues (2011)** scanned people playing a **driving game** **alone** or **watched by friends** in another room, with no interaction during play.", "children": ["Adolescents took significantly more risks when watched, though the age-by-context difference on behavior was not itself significant in this small sample.", "The **ventral striatum and orbitofrontal cortex** were more active when friends watched, and this went with risky decisions."]}, {"text": "**Cognitive-control regions** were less engaged in adolescents than adults but did **not change with peers**, so the authors concluded the peer effect works mainly through **reward circuitry**, though the two systems influence each other.", "children": ["People less resistant to peer influence showed a larger reward response; peers also raise preference for **immediate rewards**, even when only believed to be watching."]}]}, "21": {"1": [{"text": "Items that **sound alike** are harder to recall in a list than items that sound different. This is the **phonological similarity effect**, which could just as well be called the **acoustic** similarity effect.", "children": ["It holds even for **silent reading**, so no sound has to be presented."]}, {"text": "The best reading is that we **convert what we see into a speech code**. With a purely visual code the mix-ups would be between look-alikes such as E and F.", "children": ["That logic is the foundation of the **phonological loop** in working memory."]}, {"text": "The loop pairs a **phonological store** for short-lived speech traces with an **articulatory control process** that recodes visual input and refreshes traces.", "children": ["Keeping that process busy (**articulatory suppression**) blocks recoding, and for visually presented lists the sound-alike cost goes away."]}], "2": [{"text": "How well a word is held in **short-term memory** depends on how many similar words it has, which is a **long-term memory** influence: the **neighborhood size effect**.", "children": ["Neighbors are words one letter (orthographic) or one sound (phonological) away; cat has many (**large neighborhood**), hippopotamus has none (**small neighborhood**)."]}, {"text": "Words from **large neighborhoods are recalled better** than words from small neighborhoods.", "children": ["Language knowledge is shaping short-term performance."]}, {"text": "So **memory span** cannot be a clean measure of short-term capacity, because long-term memory contributes to it.", "children": []}], "3": [{"text": "The **Brown-Peterson task** pairs studying a few letters with a **distractor task**, such as counting backwards, that stops rehearsal.", "children": ["The longer the distraction, the **worse the recall**."]}, {"text": "Counting is so unlike remembering letters that the researchers judged **interference** an unlikely cause of the forgetting.", "children": []}, {"text": "They concluded that **short-term memory (STM)** holds information only briefly and loses it through **decay** unless it is rehearsed.", "children": ["This ran against the earlier view that forgetting is due to **interference**, not decay."]}], "4": [{"text": "Hearing a list gives better memory for its **final one or two items** than reading it silently. That is the **modality effect**.", "children": ["Lists that are lip-read or mouthed give the same benefit."]}, {"text": "The effect pushed theorists toward **sensory memory**: a back-up store of **raw, unanalyzed input** that helps when that information is useful.", "children": []}, {"text": "The favored account is that hearing supplies **extra information about how the items sound**, and that extra information supports the end of the list.", "children": []}], "5": [{"text": "What limits report from a brief glance is **recall**, not perception: observers see far more than they can report.", "children": []}, {"text": "The evidence is **partial report**. A cue pointing to one part of the display just after it vanishes lets that part be reported almost perfectly, whichever part it is.", "children": ["So a **sensory (iconic) store** briefly holds almost everything that was seen."]}, {"text": "Delay the cue and the advantage fades, so the store is **very short-lived**. The bottleneck is the **time it takes to report**, during which items fade.", "children": []}], "6": [{"text": "Memory for **order** is mostly right, and the mistakes follow a **pattern**: a misplaced item tends to end up **next to its true slot** and seldom far away.", "children": []}, {"text": "Because the errors are not random, people clearly keep **approximate position information**. Counting only **percent correct** treats a near miss as complete forgetting and hides this.", "children": []}], "7": [{"text": "Descriptions of our own mental images are a poor guide, because there is no way to tell whether the **images** differ or only the **descriptions** do. So we need a task that forces people to use imagery and shows it in their behavior.", "children": ["Counting the windows in your home is the kind of everyday task where we seem to inspect a **mental image**."]}, {"text": "In the classic rotation task people judged whether two block shapes were the **same or mirror images** when one was turned. They said they **mentally rotated** one shape to match the other.", "children": ["The **bigger the turn, the longer the judgment**, and the extra time rose at a **constant rate**."]}, {"text": "Rotating an image takes time, as with a real object, which suggests **mental images are much like real images**, an idea that shaped **theories of mental representation**.", "children": []}], "8": [{"text": "Probability judgments run on **heuristics**: fast shortcuts that give up some accuracy. They work day to day but can produce **wrong judgments**, and people's estimates often stray far from the true odds.", "children": []}, {"text": "The **conjunction fallacy** shows it. People say that **A and B together** is more likely than A alone or B alone, even though a combination is **never more likely than** either part.", "children": []}, {"text": "In studies where people read a short description of a person and rated how likely certain professions or activities were, they sometimes rated the **combination above a single part**, which shows reliance on **heuristics**, not probability rules.", "children": []}], "9": [{"text": "The card rule \"If D on one side, then 3 on the other\" is tested by the cards that could **break** it: **D and 7**.", "children": ["People tend to turn D and 3, but the 3 can only **confirm** the rule, and they miss the 7, which could **falsify** it."]}, {"text": "Put the same logic in a familiar rule such as \"If you borrow my car, you must fill up the tank,\" and it becomes **easy**: check the borrowed car and the empty tank.", "children": []}, {"text": "Abstract and thematic versions were compared. **Relevant experience** makes a rule testable; without it people must use **logic alone**.", "children": []}], "10": [{"text": "**How a choice is framed shapes the decision**, not just the options themselves, and many such tendencies are called **framing effects**. It is fairly easy to set up a context that steers people.", "children": []}, {"text": "What defines a **framing effect** is that the **wording or context** changes the choice even though the situations are **otherwise equivalent**.", "children": []}, {"text": "Show the same choice in **two different ways** and people choose differently. In the classic framing studies, **gain wording** typically leads to the **sure option** and **loss wording** to the **gamble**.", "children": []}], "11": [{"text": "Three doors, one prize: you choose a door, then a host who always plays fair opens a different door with nothing behind it. **Switch**, because staying keeps your original odds and switching roughly doubles them.", "children": ["Saying it makes no difference is the classic mistake."]}, {"text": "Your first guess is a long shot, and the host's reveal tells you nothing new about it. The combined chance held by the other two doors therefore **collapses onto the single door left closed**.", "children": []}, {"text": "The error comes from seeing two doors and calling it a coin flip, which overlooks that the host **could not** open your door or the prize door.", "children": []}], "12": [{"text": "**Risky choices depend on how they are framed**, even when the situations are otherwise equivalent.", "children": []}, {"text": "The standard setup offers a **sure outcome** against a **gamble**. The sure outcome can be a gain or a loss, which shows how **gain versus loss** changes the choice.", "children": []}, {"text": "The typical pattern, from prospect-theory research, is **caution with gains** (take the sure thing) and **risk-taking with losses** (take the gamble). Perception of the outcome matters, not just the odds.", "children": []}], "13": [{"text": "Young children may not get stuck on what an object is usually for, even though adults do and problem solving usually improves with age.", "children": ["German and Defeyter tested this with a toy bear that needed a box turned over as a support to reach a toy on a high shelf, sometimes after the box had been shown as a container."]}, {"text": "Older children, 6 and 7, were **slowed by the container demonstration**. The **5-year-olds were not**, and solved faster than the older children in that condition.", "children": ["With no demonstration, performance just improved with age."]}, {"text": "The likely reason is that **young children treat function as flexible**: whatever the user is trying to do can make something a tool.", "children": ["Older children hold a use more firmly and must restructure the problem to see the box as a support."]}], "14": [{"text": "Ignored speech still **disrupts recall of an ordered list**, and speech with changing syllables does more damage than one repeated syllable.", "children": ["Theories disagree about why: it may corrupt sound-based memory traces, break up order rehearsal, or capture attention."]}, {"text": "The test was whether speech also disrupts memory for **locations**, in children and adults. It **did not**: only **word-like items** suffered.", "children": ["Children were hit harder than adults, even by repeated-syllable speech, although the extra cost of changing syllables was similar in both groups."]}, {"text": "That points to **interference with sound-based codes** and causes trouble for accounts that predict damage to any kind of item.", "children": []}], "15": [{"text": "Writing things down is a way of **taking load off memory**.", "children": ["The question was whether people use it when they most need it, and whether it works."]}, {"text": "When lists got longer than memory can hold, people **used the notepad more and remembered more** because of it.", "children": []}, {"text": "The expected link to **poor memory ability did not appear**: weaker and stronger memories offloaded alike, and gained alike.", "children": ["That suggests offloading **may help people of many abilities**."]}], "16": [{"text": "The **bat-and-ball puzzle** pulls people to answer 10 cents. Subtracting $1.00 from $1.10 leaves the bat only 90 cents more, so the right answer is **5 cents**.", "children": []}, {"text": "One account says wrong answers come from **swapping in an easier question** without noticing.", "children": ["Evidence for it: wrong reasoners were **less sure of themselves** than on a version without 'more than', as if they sensed a problem."]}, {"text": "A later study found those reasoners often **still remembered the phrase 'more than'** but apparently did not use it, so the error may be **conscious** rather than hidden.", "children": ["Others lost the phrase or stayed confident, so substitution can still happen for some.", "Because the cause cannot be pinned down, the authors call the confidence drop **error sensitivity**."]}], "17": [{"text": "Two known influences on choice were tested together: **wording** (people take the sure thing when outcomes are gains and gamble when they are losses) and **defaults** (people drift to whatever is preselected).", "children": []}, {"text": "When choices were about lives or about money, with the sure or the risky option preselected, **wording kept its usual effect** and the effects of wording and default simply **added up**.", "children": ["A **risky default pushed people toward risk**, while a **sure default did not make them more cautious** overall.", "Risk was higher when lives were at stake, though involvement also differed from the money case."]}, {"text": "Why people followed or rejected the default seemed to go with **what they thought it was**: most rational, expert advice, or chance.", "children": ["That was an after-the-fact, exploratory question, so it may reflect justification more than cause."]}], "18": [{"text": "Teens reason about risk about as well as adults when alone, so the extra real-world risk is attributed to **the social setting**.", "children": ["Experiments show teens take more risks with friends present than alone, and adults do not."]}, {"text": "In a brain-scan driving game, teens played alone or with friends **watching from another room** and not interacting.", "children": ["When watched, **reward areas became more active** in teens and this went with riskier choices, even though the behavior gap between age groups was not itself firm in a small sample."]}, {"text": "**Control areas did not change with an audience**, so the effect seems to come mainly from **stronger reward response** rather than weaker self-control, although the two systems interact.", "children": ["Peers also push toward immediate rewards, even when only believed to be watching."]}]}, "22": {"1": [{"text": "Conrad (1964) found that items that **sound alike** are harder to recall as a list than items that sound different, the **phonological similarity effect**; sound is what matters, so **acoustic similarity effect** is arguably the better name.", "children": ["It holds even for **silent reading**, so no sound has to be presented."]}, {"text": "The best reading is that we **convert what we see into a speech code**. With a purely visual code the mix-ups would be between look-alikes such as E and F.", "children": ["Baddeley (1986) built the **phonological loop** of working memory on this logic."]}, {"text": "The loop pairs a **phonological store** for short-lived speech traces with an **articulatory control process** that recodes visual input and refreshes traces.", "children": ["Murray (1968) kept that process busy with **articulatory suppression** to block recoding; with visually presented lists the sound-alike cost goes away."]}], "2": [{"text": "Roodenrys et al. (2002) showed that **long-term memory factors affect short-term memory**: a word's **neighborhood**, the words one letter (orthographic) or one sound (phonological) away, changes how well it is recalled.", "children": ["Cat has many neighbors (**large neighborhood**); hippopotamus has none (**small neighborhood**)."]}, {"text": "In their short-term memory task, **large neighborhood words were recalled better** than small neighborhood words.", "children": ["Stored knowledge about words is boosting short-term performance."]}, {"text": "Therefore **memory span** cannot be a clean measure of short-term capacity, because long-term memory contributes to it.", "children": []}], "3": [{"text": "In the **Brown-Peterson task** people studied a few letters and then did a **distractor task**, counting backwards, that stopped rehearsal; Peterson and Peterson (1959) found that the longer the distraction, the **worse the recall**.", "children": ["Counting is so unlike remembering letters that they judged **interference** an unlikely cause."]}, {"text": "Their conclusion was that **short-term memory (STM)** holds information only briefly and loses it through **decay** unless it is rehearsed.", "children": ["This went against the view that followed McGeoch's (1932) critique, that forgetting is due to **interference**."]}, {"text": "Decay is the original researchers' conclusion, not the only reading: Keppel and Underwood (1962) are cited as offering an alternative explanation.", "children": []}], "4": [{"text": "The **modality effect** is a memory advantage for the **last one or two items** of a **heard** list over a silently read one, and it also shows up with lip-read or mouthed lists.", "children": []}, {"text": "It strongly shaped thinking about **sensory memory**, a back-up store holding **raw, unanalyzed sensory input** that can help recall.", "children": []}, {"text": "Neath and Surprenant (2003) give the favored explanation: **hearing adds a further kind of information**, how the list sounds, and this helps the final items.", "children": []}], "5": [{"text": "Sperling (1960) challenged the idea that perception caps how much we take in from a brief glance. The cap, he argued, is on **recall**.", "children": []}, {"text": "His **partial-report** method cued observers toward one part of the display as it vanished, and whichever part was cued came out nearly intact.", "children": ["That implies a **sensory (iconic) store** briefly held almost the whole display."]}, {"text": "A delayed cue lost the advantage, so the store **fades quickly**, and full report is limited because items disappear **while being reported**.", "children": []}], "6": [{"text": "Order memory shows a clear pattern: each item most often comes back in its own slot.", "children": []}, {"text": "When it does not, the item usually lands one place away, so the third item of a list is more likely to appear second or fourth than first or last. The errors are **systematic**, not random.", "children": []}, {"text": "That means forgetting a position is **not the same as losing the item**. Percent correct alone makes it look like **lost information**, but people retain **approximate position information**.", "children": []}], "7": [{"text": "Self-descriptions of mental images are unreliable, so imagery is studied with tasks that force it, as in Shepard and Metzler (1971). People judged whether two block shapes were the **same or mirror images** when one was turned, and said they **mentally rotated** one shape to match the other.", "children": ["The **bigger the turn, the longer the judgment**, and the extra time rose at a **constant rate**."]}, {"text": "Everyday tasks such as counting the windows in your home seem to rely on a **mental image**, and these results suggest such images are treated **much like real images**.", "children": ["Rotating an image takes time, as with a real object."]}, {"text": "Shepard and Metzler's (1971) findings shaped **theories of mental representation**.", "children": []}], "8": [{"text": "Tversky and Kahneman (1983) showed that probability judgments run on **heuristics**: fast shortcuts that give up some accuracy. They work day to day but can produce **wrong judgments**.", "children": []}, {"text": "The **conjunction fallacy** shows it. People say that **A and B together** is more likely than A alone or B alone, even though a combination is **never more likely than** either part.", "children": []}, {"text": "Shafir, Smith, and Osherson (1990) had people read a short description of a person and rate how likely certain professions or activities were. They sometimes rated the **combination above a single part**, which shows reliance on **heuristics**, not probability rules.", "children": []}], "9": [{"text": "The **Wason Selection Task** asks which cards to turn over to check \"If a card has a D on one side, it has a 3 on the other.\" Only **D and 7** could **falsify** it.", "children": ["A common choice is D and 3, yet the 3 can only **confirm** the rule, while the 7 goes unchecked."]}, {"text": "A familiar rule with identical logic, \"If you borrow my car, you must fill up the tank,\" is **far easier**, since the borrowed car and the empty tank are the obvious cards to check.", "children": []}, {"text": "Wason and Shapiro (1971) compared abstract with thematic rules and concluded that **relevant experience** lets people test a rule, whereas abstract rules leave only **logic**.", "children": []}], "10": [{"text": "**How a choice is framed shapes the decision**, not just the options themselves. Kahneman and Tversky (1982) summarized many of these **framing effects**.", "children": []}, {"text": "What defines a **framing effect** is that the **wording or context** changes the choice even though the situations are **otherwise equivalent**.", "children": []}, {"text": "Tversky and Kahneman's classic framing studies showed the same choice in **two different ways**, and **gain wording** typically led to the **sure option** while **loss wording** led to the **gamble**.", "children": []}], "11": [{"text": "The **Monty Hall 3 Door problem** is a test of how people handle **combinations of events**. You pick a door, the host who always plays fair opens an empty one, and the best move is to **switch**.", "children": ["Always switching wins about **two-thirds** of the time, always staying about **one-third**."]}, {"text": "Why: the first pick holds a **1 in 3** chance, so the other two doors together hold **2 in 3**. The reveal does not change your door's chance, so all **2 in 3** now sits behind the one remaining door.", "children": []}, {"text": "Most people say the two doors are equally likely and that it makes no difference. That is **wrong**, because the host's choice of which door to open is not random.", "children": []}], "12": [{"text": "Kahneman and Tversky (1982) summarized many **framing effects**, in which the same situation described differently draws a different choice, and risky decisions are a prime case.", "children": []}, {"text": "Researchers set a **guaranteed outcome** against a **gamble** with stated chances of winning and losing, and make the guaranteed outcome either a gain or a loss to see what that does to the choice.", "children": []}, {"text": "Kahneman and Tversky's prospect-theory work gives the typical result: with gains people **play it safe** and take the sure thing, while with losses they **gamble**. How an outcome is perceived drives the decision, not only the odds.", "children": []}], "13": [{"text": "**German and Defeyter (2000)** asked whether children share the **functional fixedness** that **Duncker (1945)** found with the candle problem and **Adamson (1952)** found in adults.", "children": ["Because problem solving improves with age, the general expectation was that younger children would do worse.", "Their box task had a toy bear reach a toy on a high shelf by using a box as a support, after the box was or was not shown as a container."]}, {"text": "**Children of 6 and 7 were slowed** by the container demonstration, but **5-year-olds were immune** and solved faster than the older children in that condition.", "children": ["Without the demonstration, children improved with age."]}, {"text": "**German and Johnson (1997)** proposed that **young children have a more fluid idea of function**, and German and Defeyter predicted the immunity from it.", "children": ["Older children hold function rigidly and must **restructure** the container use to see a support."]}], "14": [{"text": "**Salamé and Baddeley (1982)**, **Jones and colleagues**, and **Cowan (1995)** offered competing explanations of why ignored speech disrupts serial recall: phonological traces, order rehearsal, and attention capture.", "children": ["Changing-state speech does more damage than steady-state speech."]}, {"text": "**Leist and colleagues (2022)** showed that speech **did not disrupt spatial recall** in either children or adults, only verbal recall, unlike the equal effects reported by **Jones and colleagues (1995)**.", "children": ["Children were more impaired than adults relative to silence, but the added cost of changing-state speech was about the same in both groups."]}, {"text": "Leist and colleagues concluded the effect is **specific to verbal material**, which challenges the **attention-capture** and **changing-state** accounts and fits **similarity-based interference** with phonological codes.", "children": []}], "15": [{"text": "**Risko and Gilbert (2016)** defined offloading as using actions to reduce a task's mental demands.", "children": ["**Morrison and Richmond (2020)** tested whether people with weaker working memory offload more, as **Risko and Dunn (2015)** had reported."]}, {"text": "**Morrison and Richmond (2020)** found that offloading helped most at **high loads** and rose with load, matching Risko and Dunn (2015).", "children": []}, {"text": "They did **not** replicate Risko and Dunn's link between memory ability and offloading, and ability did not predict the benefit, so offloading **may be a compensatory strategy** across abilities.", "children": []}], "16": [{"text": "**Frederick (2005)** used the **bat-and-ball problem**: 10 cents feels right, but 5 cents is correct because the bat must cost a dollar more.", "children": []}, {"text": "**Kahneman and Frederick (2002)** proposed **attribute substitution**, and **De Neys, Rossi and Houdé (2013)** showed wrong reasoners were **less confident** than on a control version, a **substitution sensitivity**.", "children": []}, {"text": "**Hoover and Healy (2019)** found wrong reasoners mostly **remembered 'more than'** but apparently did not use its meaning, evidence for a **conscious error process**.", "children": ["Because some lost the phrase and many stayed confident, substitution may still occur for some reasoners.", "Hoover and Healy prefer **error sensitivity** because they cannot be sure the error was substitution."]}], "17": [{"text": "**Giuliani and colleagues (2023)** joined the **framing effect** of **Tversky and Kahneman (1981)** to the **default effect** shown in organ donation by **Johnson and Goldstein (2003)**.", "children": []}, {"text": "They found a **classic framing effect** and more risk taking with lives than money (as in **Fagley and Miller, 1997**), though lives were another country's and money was the participant's own.", "children": ["A **risky default raised risk taking** while a **sure default did not raise risk aversion** overall, so in some circumstances people are nudged toward risk more easily than toward certainty.", "Framing and default effects were **additive**."]}, {"text": "In **Giuliani and colleagues' (2023)** exploratory question after the choice, belief in the default as **most rational** went with following it most, **expert advice** with indifference, and **previous respondents or chance** with rejection.", "children": ["Beliefs may partly be justification of a choice already made."]}], "18": [{"text": "**Albert, Chein and Steinberg (2013)** point to the peer context, citing **Gardner and Steinberg (2005)**, where adolescents, but not adults, took more risks with peers than alone.", "children": ["Their model is a **maturational gap** between a peer-primed **reward system** and a slowly maturing **cognitive-control system**."]}, {"text": "**Chein, Albert, O'Brien, Uckert and Steinberg (2011)** scanned a **driving game** played alone or watched by friends, and found adolescents took significantly more risks when watched.", "children": ["Reward regions (**ventral striatum, orbitofrontal cortex**) were more active in adolescents when peers watched, going with risky decisions."]}, {"text": "**Chein and colleagues (2011)** found **cognitive-control regions did not change with peers**, so they concluded the effect works mainly through **reward circuitry**; **Albert and colleagues (2013)** note the two systems interact.", "children": ["**O'Brien et al. (2011)** and **Weigard et al. (2011)** add that peers raise preference for immediate rewards, even when only believed present."]}]}, "r20": {"1": [{"text": "The **phonological similarity effect** is the finding that people recall a list **worse when its items sound alike** than when they sound different. Since the sound is what matters, **acoustic similarity effect** is arguably the better name.", "children": ["On each trial, letters appeared one at a time, and people then clicked the letters in the order shown. Half the lists had letters that sound alike and half had letters that sound different.", "The surprising part is that it still happens when people **read the items silently**, with no sound presented."]}, {"text": "Silent reading still producing it means people **recode what they see into a speech-based form**. If memory held only a visual code, the mix-ups would be between items that **look** alike, such as E and F, instead of items that **sound** alike.", "children": ["This recoding is the basis of the **phonological loop**, a component of **working memory**."]}, {"text": "The loop has a **phonological store**, which briefly holds speech-based traces, and an **articulatory control process**, which converts visual input into a speech code and refreshes the traces.", "children": ["**Articulatory suppression** keeps that control process busy, so visual items cannot be recoded.", "On some trials people said \"one, two, three, four\" out loud over and over until the response buttons became active (articulatory suppression), and on other trials they stayed quiet.", "With recoding blocked, visually presented lists that sound alike and lists that sound different are **recalled equally well**."]}], "2": [{"text": "The **neighborhood size effect** shows that **knowledge stored in long-term memory changes short-term memory performance**. A word's **neighborhood** is every word you can make by changing one letter (**orthographic**) or one sound (**phonological**).", "children": ["Cat has many neighbors, such as bat, cot and can, so it is a **large neighborhood word**; hippopotamus has none, so it is a **small neighborhood word**."]}, {"text": "Roodenrys and colleagues (2002) found that in short-term memory tasks, **large neighborhood words are recalled better** than small neighborhood words.", "children": ["People saw a sequence of words and then clicked buttons for the words in the order they were presented (immediate serial recall).", "So what a person knows about the language helps them hold words briefly."]}, {"text": "This causes trouble for **memory span**. If long-term memory affects it, span **cannot be a pure measure of short-term memory capacity**.", "children": []}], "3": [{"text": "The **Brown-Peterson task** was designed to test what happens to information in **short-term memory** when it cannot be rehearsed. People studied a few consonants and then did a hard **distractor task**, counting backwards, which stopped them from rehearsing the letters.", "children": ["Peterson and Peterson (1959) ran this task.", "On each trial people saw a consonant trigram (three consonants) for a moment, then a three-digit number, and counted backwards out loud by 3 for several seconds before being asked to recall the trigram."]}, {"text": "The longer the distractor lasted, the **less likely people were to recall the letters**.", "children": ["Counting backwards is very different from remembering letters, so the researchers judged **interference** an unlikely cause of the forgetting."]}, {"text": "Their conclusion was that **short-term memory (STM)** holds information only briefly, and that without rehearsal the information is lost through **decay**.", "children": ["Decay is the researchers' own conclusion; the results have also been given an alternative explanation."]}], "4": [{"text": "The **modality effect** is a better memory for the **last one or two items** of a list when the list is **heard** than when it is read silently.", "children": ["On each trial people either heard or saw the digits 1 through 9 in random order and then clicked the digits in the order presented. Half the trials were auditory and half were visual.", "It also appears for lists that are **lip-read** or **silently mouthed**, so it is not only about hearing."]}, {"text": "These findings strongly influenced the idea of **sensory memory**, a back-up store that holds **raw, unanalyzed sensory input** and can improve recall when that information is useful.", "children": []}, {"text": "The favored explanation, from Neath and Surprenant (2003), is that **hearing provides an additional type of information** compared with reading.", "children": ["When recalling the last items, you do better if you also have information about **how the list sounded**."]}], "5": [{"text": "Early work found that people could report only a small part of a brief display. Sperling (1960) suggested this limit came from **recall**, not from perception.", "children": ["He used the **partial-report** method, in which a cue given after the display tells observers which part to report.", "A three-by-three matrix of letters flashed very briefly. After it disappeared, a high, medium or low tone told the observer to report the top, middle or bottom row, and the tone could come right away or after a delay."]}, {"text": "When the cue came **right after the display disappeared**, observers reported the cued part almost perfectly, whichever part it was.", "children": ["So a **sensory (iconic) store** briefly held nearly a complete copy of the display."]}, {"text": "The real limit is the **time needed to report**, because the store fades while the observer is reporting.", "children": ["When the cue was **delayed**, performance fell back toward the usual limit, which shows how **briefly** the store lasts."]}], "6": [{"text": "The **position error effect** concerns memory for **order** as well as for items, such as the digits of a phone number. Most of the time an item is **recalled in its correct position**.", "children": ["When a mistake is made, it is **systematic**, not random.", "On each trial letters appeared one at a time, and people then clicked the letters in the order shown. The position where each recalled letter was placed was compared with its true position."]}, {"text": "A misplaced item most likely comes out in an **adjacent position**: an item that is not recalled third is probably recalled second or fourth, and rarely far from where it belongs.", "children": []}, {"text": "This matters because **percent correct alone makes forgetting look like lost information**. In fact people still remember **roughly where the item belonged**.", "children": []}], "7": [{"text": "The main theme is that **mental images behave like real images**. People report using mental images, such as when counting the windows in their home, but asking them to describe their images is unreliable, since it is impossible to tell whether the images differ or only the descriptions do.", "children": ["So researchers use **tasks that require imagery** and vary one critical part of the task, which lets them work out objectively what images are like."]}, {"text": "Shepard and Metzler (1971) showed people two block shapes and asked whether they were the **same shape or mirror images**, with one shape turned relative to the other. People said they **mentally rotated** one shape to match the other.", "children": ["Two block shapes appeared side by side, either identical or mirror images, with one rotated by different angles. People judged same or different as quickly as possible, and reaction time was recorded.", "The **larger the turn, the longer the response**, and the extra time grew at a **constant rate**."]}, {"text": "So rotating a mental image takes time, just as turning a real object does, which suggests **mental images are much like real images**.", "children": ["This finding influenced **theories of mental representation**."]}], "8": [{"text": "The main theme is that people judge probability with **heuristics**, which **trade accuracy for speed**. Heuristics are usually good enough day to day, but they can lead to **incorrect judgments**.", "children": ["Tversky and Kahneman (1983) showed that people's estimates of probability often differ greatly from objective probability."]}, {"text": "A striking example is the **conjunction fallacy**: judging that **A and B together are more likely than A alone or B alone**.", "children": ["By objective probability, a combination can **never be more likely than** either part on its own."]}, {"text": "Shafir, Smith and Osherson (1990) had people read short descriptions of a person and rate how likely it was that the person had certain professions or took part in certain activities. People sometimes rated the **combination as more likely than one part of it**.", "children": ["People read short descriptions of a person and rated, on a scale from impossible to certain, how likely it was that the person had a profession or did an activity, including combinations of the two.", "This points to reliance on **heuristics** rather than the rules of probability."]}], "9": [{"text": "People find it hard to test an **abstract rule**. In the **Wason Selection Task**, the rule is \"If a card has a D on one side, it has a 3 on the other side,\" and the job is to choose the cards that could show the rule is broken.", "children": ["The correct cards are **D and 7**, because a D without a 3, or a 7 with a D behind it, would **falsify** the rule.", "Most people pick D and 3, but the 3 can only **confirm** the rule, since the rule says nothing about what must be behind a 3."]}, {"text": "A rule with the same logic but familiar content, such as \"If you borrow my car, you must fill up the gas tank,\" is **much easier**.", "children": ["The right cards are **\"borrowed car\" and \"empty gas tank,\"** because those could reveal someone who borrowed the car and did not fill it."]}, {"text": "Wason and Shapiro (1971) compared abstract and thematic rules. People test a rule well when they have **relevant experience**.", "children": ["People saw a rule and four cards and chose the two cards to turn over to see if the rule was true. Half the rules were abstract (letters and numbers) and half were thematic (like borrowing a car).", "With thematic rules they use experience; with abstract rules they must rely **solely on logic**."]}], "10": [{"text": "The main theme is that **decisions are shaped by how a choice is framed**, not only by what the options are. People would like to weigh their options carefully, but many tendencies, called **framing effects**, push them in particular directions.", "children": ["It is fairly easy to create a context in which people choose a particular option."]}, {"text": "In a **framing effect**, the **perceived context or wording of the choice** makes a big difference, even when the situations are **otherwise equivalent**.", "children": ["Kahneman and Tversky (1982) summarized many framing effects."]}, {"text": "The same choice can be presented in **two different ways**, and people choose differently depending on the version.", "children": ["People read a description of a situation and chose between two options. Two sets of questions asked essentially the same things but framed differently, and one set was randomly given to each person.", "**Gain wording** typically pushes people toward the **sure option** and **loss wording** toward the **gamble**, so the choice follows the framing and not the substance."]}], "11": [{"text": "The main theme is that **intuition about probability is often wrong**, and the **Monty Hall 3 Door problem** is the classic example. A prize is behind one of three doors, you pick one, and the host, who is assumed to play fair and always do this, opens one of the other two doors to show **no prize**. Should you **stay or switch**?", "children": ["Many people think it does not matter, which is **incorrect**.", "On each trial people picked one of three doors, one of the other doors opened to show no prize, and then they chose to stay or switch. The lab counts how often each choice wins over many trials."]}, {"text": "**The right choice is to switch.** Always switching wins about **two-thirds** of the time and always staying wins about **one-third**.", "children": ["Most people miss this because they treat the two remaining doors as equally likely."]}, {"text": "Your first pick has a **1 in 3 chance** of being right, so there is a **2 in 3 chance** the prize is behind one of the other two doors.", "children": ["When the host shows that one of those doors is empty, that whole **2 in 3 chance moves to the remaining door**, while your own door stays at 1 in 3."]}], "12": [{"text": "The main theme is that **risky choices depend on framing**: the way a choice is framed makes a big difference to the decision, even when the situations are **otherwise equivalent**.", "children": ["This research looks at how the framing of a risky choice changes the decision."]}, {"text": "In this research people choose between a **guaranteed outcome** and a **gamble** with a stated chance of winning and a stated chance of losing.", "children": ["The guaranteed outcome can be a gain or a loss, so researchers can see how **risk, stakes, and gain versus loss** affect the choice.", "People played a wheel-of-fortune game starting with a sum of money. Each trial showed the chances and amounts of winning or losing if they gambled, and the amount guaranteed if they did not."]}, {"text": "People typically **avoid risk when the choice is about gains**, taking the sure thing, and **seek risk when the choice is about losses**, taking the gamble.", "children": ["So risky decisions depend on how outcomes are **perceived**, not just on the objective odds."]}], "13": [{"text": "German and Defeyter (2000) asked whether young children show **functional fixedness**: being stuck on an object's **usual function**, so that a new use is slow or missed.", "children": ["Problem solving normally improves with age, so younger children were expected to do worse.", "In the task, a toy bear wanted to reach a toy on a high shelf, and the solution was to turn a box over and use it as a support. In one condition the box had first been shown being used as a container.", "Sixty children aged 5, 6 and 7 helped a toy bear reach a toy on a high shelf, using objects on a table such as blocks, a ball, a pencil and a box. The solution was to turn the box over and stack bricks on it. In the preutilization condition the other objects started inside the box, showing it as a container; in the no-preutilization condition they sat beside it. The time taken to offer the box solution was measured."]}, {"text": "**Older children (6 and 7) were slower** to use the box as a support once its container use had been shown, while **5-year-olds were immune** and were even faster than the older children in that condition.", "children": ["Without the container demonstration, children simply got better with age."]}, {"text": "The authors predicted this result: **younger children have a more fluid idea of function**, where any goal of the user can make an object's function.", "children": ["Older children hold function more rigidly, so the demonstrated container use has to be **restructured** before the box can become a support."]}], "14": [{"text": "The **irrelevant speech effect** is that speech you are told to ignore **impairs serial recall**, and **changing-state speech** (different syllables) hurts more than **steady-state speech** (one syllable repeated).", "children": ["Accounts differ: the speech may corrupt **phonological traces**, changing sound may disrupt **order rehearsal** for any item, or sound may **capture attention**.", "Leist and colleagues (2022) separated these accounts by testing **verbal** and **spatial** items in children and adults.", "Third-grade children and adults reconstructed the order of a list of pictured objects (the verbal task) or of dot locations (the spatial task), clicking after a short delay. Each person did one of the two tasks while hearing quiet, a repeated syllable (steady-state) or different syllables (changing-state), which they were told to ignore."]}, {"text": "Speech **impaired verbal recall but not spatial recall**, in both children and adults.", "children": ["Children were more impaired than adults relative to silence, and they were hurt by steady-state speech too, which adults were not."]}, {"text": "So the effect is **specific to verbal material**.", "children": ["That is hard for the **attention-capture** and **changing-state** accounts, which predict disruption of spatial items too.", "It fits **similarity-based interference** between the speech and the **phonological representations** of the list."]}], "15": [{"text": "**Cognitive offloading** is using actions such as writing things down to **reduce the mental demands** of a task.", "children": ["Morrison and Richmond (2020) asked who offloads and whether it helps.", "They expected people with **lower working memory capacity** to offload more.", "Students heard lists of letters of different lengths and said them back in order. In the no-choice block they relied on memory alone; in the choice block they had pen and paper and could write anything down if they wished. They also completed working memory span tasks to measure working memory capacity."]}, {"text": "**Offloading improved memory**, especially at **high loads** beyond short-term memory capacity, and people **offloaded more as the load grew**.", "children": []}, {"text": "**Memory ability did not predict who offloaded**, and capacity did not predict the benefit either.", "children": ["So offloading **may be a compensatory strategy** that helps across a wide range of memory ability."]}], "16": [{"text": "In the **bat-and-ball problem**, a bat and ball cost $1.10 together and the bat costs $1.00 more than the ball.", "children": ["The intuitive answer is **10 cents**, but then the bat is only 90 cents more.", "The correct answer is **5 cents**: ball x, bat x plus $1.00, so x is 5 cents."]}, {"text": "One account of the error is **unconscious attribute substitution**: reasoners neglect 'more than' and answer an easier question.", "children": ["Support for it came from incorrect reasoners being **less confident** on the standard problem than on a control without 'more than', called **substitution sensitivity**."]}, {"text": "Hoover and Healy (2019), using matching problems, found that incorrect reasoners mostly **recalled and recognized 'more than'**, so it was not simply overlooked, but they apparently did not use its meaning.", "children": ["Online, people answered a standard problem with 'more than' and a control version without it, using unfamiliar items such as pencil and eraser. After each, they rated their confidence and gave an opinion of how many other people would solve it. Later they were asked to recall the problem and to recognize its wording, with simple math problems put in between as interference for most participants.", "Some reasoners did lose the phrase and many stayed very confident, so substitution may still occur for some.", "Because they cannot be sure the error was substitution, they prefer the term **error sensitivity**."]}], "17": [{"text": "Giuliani and colleagues (2023) combined the **framing effect**, where people prefer the **sure option for gains** and the **risky option for losses**, with the **default effect**, a tendency to take the **preselected option**.", "children": ["The Asian disease problem is the classic framing example: 'saved' wording favors the sure program and 'die' wording favors the risky one.", "The two effects had mostly been studied separately."]}, {"text": "People made **life-or-death** and **financial** choices with **no default**, a **sure default**, or a **risky default**.", "children": ["Each person was randomly assigned to one of six conditions: gain or loss wording, each with no default, a sure default or a risky default. Everyone chose in two scenarios, a life-or-death problem and an economic-crisis problem about their own money. With a default, the preselected option was flagged and people were asked whether they would change it. Afterward, those with a default chose a reason for why it was preselected.", "They found a **classic framing effect** and **more risk taking when lives were at stake**, although lives concerned people elsewhere while the money was the participant's own, so involvement differed.", "A **risky default raised risk taking**, a **sure default did not raise risk aversion**, and framing and default were **additive**."]}, {"text": "Afterward people said why they thought the option was preselected. Those who saw it as the **most rational choice** followed it most, **expert advice** left people indifferent, and **previous respondents or chance** went with rejecting it.", "children": ["This question was exploratory and came after the choice, so beliefs may partly justify a choice already made."]}], "18": [{"text": "Albert, Chein and Steinberg (2013) reviewed why adolescents take more risks in real life although they **reason about risk as well as adults in the lab**.", "children": ["Their answer is the **peer context**: adolescents take more risks with peers present than alone, and adults do not.", "Peers prime the **reward system** (ventral striatum, orbitofrontal cortex) while the **cognitive-control system** (lateral prefrontal cortex) matures slowly, a **maturational gap**."]}, {"text": "Chein and colleagues (2011) scanned people playing a **driving game** **alone** or **watched by friends** in another room, with no interaction during play.", "children": ["Adolescents took significantly more risks when watched, though the age-by-context difference on behavior was not itself significant in this small sample.", "Adolescents, young adults and adults played the Stoplight driving game in a scanner. At each yellow light they decided whether to go, risking a crash, or to stop and wait. Each person played alone and with two friends watching from the control room, and later filled out questionnaires including resistance to peer influence.", "The **ventral striatum and orbitofrontal cortex** were more active when friends watched, and this went with risky decisions."]}, {"text": "**Cognitive-control regions** were less engaged in adolescents than adults but did **not change with peers**, so the authors concluded the peer effect works mainly through **reward circuitry**, though the review points out that the two systems influence each other.", "children": ["People less resistant to peer influence showed a larger reward response; peers also raise preference for **immediate rewards**, even when only believed to be watching."]}]}, "r21": {"1": [{"text": "Items that **sound alike** are harder to recall in a list than items that sound different: the **phonological similarity effect**, or more accurately the **acoustic similarity effect**.", "children": ["Letters appeared one at a time, and people clicked them in the order shown; half the lists sounded alike and half sounded different.", "It appears even when the list is **read silently**."]}, {"text": "The explanation is that people **convert what they see into a speech code**. A purely visual code would instead produce mix-ups between look-alikes such as E and F.", "children": ["This is the foundation of the **phonological loop** of working memory."]}, {"text": "The loop pairs a **phonological store** for short-lived speech traces with an **articulatory control process** that recodes visual input and refreshes the traces.", "children": ["On some trials people repeated \"one, two, three, four\" aloud while studying, and on others they stayed quiet.", "Occupying that process (**articulatory suppression**) blocks recoding, and the sound-alike cost disappears for visually presented lists."]}], "2": [{"text": "How well a word is held in **short-term memory** depends on how many similar words exist, which is a **long-term memory** influence: the **neighborhood size effect**.", "children": ["Neighbors are words one letter (orthographic) or one sound (phonological) away; cat has many (**large neighborhood**), hippopotamus has none (**small neighborhood**)."]}, {"text": "**Large neighborhood words are recalled better** than small neighborhood words, so language knowledge is shaping short-term performance.", "children": ["People saw a sequence of words and clicked them back in the order presented."]}, {"text": "As a result, **memory span** is not a clean measure of short-term capacity.", "children": []}], "3": [{"text": "In the **Brown-Peterson task**, people study a few letters and then do a **distractor task**, such as counting backwards, that stops rehearsal.", "children": ["The longer the distraction, the **worse the recall**.", "People saw three consonants, then counted backwards by 3 from a three-digit number for several seconds before recalling the consonants."]}, {"text": "Counting is so unlike remembering letters that **interference** seemed an unlikely cause of the forgetting.", "children": []}, {"text": "The conclusion was that **short-term memory (STM)** holds information only briefly and loses it through **decay** unless it is rehearsed.", "children": ["That is the researchers' conclusion, and an alternative explanation of the results exists."]}], "4": [{"text": "Hearing a list gives better memory for its **final one or two items** than reading it silently: the **modality effect**.", "children": ["People heard or saw digits in random order and clicked them back in the order presented, half the trials auditory and half visual.", "Lip-read or mouthed lists give the same benefit."]}, {"text": "The effect pushed theories toward **sensory memory**, a back-up store of **raw, unanalyzed input** that helps when that information is useful.", "children": []}, {"text": "The favored account is that hearing supplies **extra information about how the items sound**, and that supports the end of the list.", "children": []}], "5": [{"text": "What limits report from a brief glance is **recall**, not perception: observers see far more than they can report.", "children": []}, {"text": "The evidence is **partial report**. A cue to one part of the display just after it vanishes lets that part be reported almost perfectly, whichever part it is.", "children": ["A three-by-three matrix of letters flashed briefly, and after it disappeared a high, medium or low tone cued the top, middle or bottom row to report.", "So a **sensory (iconic) store** briefly holds almost everything that was seen."]}, {"text": "Delay the cue and the advantage fades, so the store is **very short-lived**. The bottleneck is the **time it takes to report**, during which items fade.", "children": []}], "6": [{"text": "Memory for **order** is mostly right, and the mistakes follow a **pattern**: a misplaced item tends to land **next to its true position**, seldom far away.", "children": ["Letters appeared one at a time and people clicked them back in order; where each letter was placed was compared with its true position."]}, {"text": "Because the errors are systematic, people keep **approximate position information**. Counting only **percent correct** treats a near miss as complete forgetting and hides this.", "children": []}], "7": [{"text": "Reports about our own mental images are a poor guide, because there is no way to tell whether the **images** differ or only the **descriptions** do. So tasks are used that force imagery and show it in behavior.", "children": []}, {"text": "In the rotation task, people judged whether two block shapes were the **same or mirror images** when one was turned, and said they **mentally rotated** one to match the other.", "children": ["Two block shapes appeared, identical or mirror images, one rotated by different angles, and people judged same or different as quickly as possible.", "The **bigger the turn, the longer the judgment**, rising at a **constant rate**."]}, {"text": "Rotating an image takes time, as with a real object, so **mental images are much like real images**, an idea that shaped **theories of mental representation**.", "children": []}], "8": [{"text": "Probability judgments rely on **heuristics**: quick shortcuts that give up some accuracy. They usually work, but can produce **wrong judgments**, and estimates often stray far from the true probability.", "children": []}, {"text": "The **conjunction fallacy** shows this: people say **A and B together** is more likely than A alone or B alone, although a combination is **never more likely than** either part.", "children": []}, {"text": "When people read a short description of a person and rated the likelihood of professions or activities, they sometimes rated the **combination above a single part**, which indicates **heuristics**, not probability rules.", "children": ["People rated how likely each description fit a profession or an activity, including combinations of the two, on a scale from impossible to certain."]}], "9": [{"text": "The card rule \"If D on one side, then 3 on the other\" is tested by the cards that could **break** it: **D and 7**.", "children": ["People tend to turn D and 3, but the 3 can only **confirm** the rule, and they miss the 7, which could **falsify** it."]}, {"text": "Put the same logic in a familiar rule such as \"If you borrow my car, you must fill up the tank,\" and it becomes **easy**: check the borrowed car and the empty tank.", "children": []}, {"text": "**Relevant experience** makes a rule testable; without it, as with abstract rules, people must use **logic alone**.", "children": ["People saw a rule and four cards and picked two to turn over, with half the rules abstract and half thematic."]}], "10": [{"text": "**How a choice is framed shapes the decision**, not just the options themselves. Many such tendencies are called **framing effects**, and it is fairly easy to set up a context that steers people.", "children": []}, {"text": "A **framing effect** means the **wording or context** changes the choice even though the situations are **otherwise equivalent**.", "children": []}, {"text": "Show the same choice in **two different ways** and people choose differently: **gain wording** typically leads to the **sure option** and **loss wording** to the **gamble**.", "children": ["People read situations and chose between two options. Two question sets were framed differently, and each person was randomly given one."]}], "11": [{"text": "Three doors, one prize: you choose a door, then a host who always plays fair opens a different door with nothing behind it. **Switch**, because staying keeps your original odds and switching roughly doubles them.", "children": ["People picked a door, saw another open empty, and then stayed or switched, with wins counted over many trials.", "Saying it makes no difference is the classic mistake."]}, {"text": "Your first guess is a long shot, and the host's reveal tells you nothing new about it. The combined chance held by the other two doors therefore **collapses onto the single door left closed**.", "children": []}, {"text": "The error comes from seeing two doors and calling it a coin flip, which overlooks that the host **could not** open your door or the prize door.", "children": []}], "12": [{"text": "**Risky choices depend on how they are framed**, even when the situations are otherwise equivalent.", "children": []}, {"text": "The standard setup offers a **sure outcome** against a **gamble**. The sure outcome can be a gain or a loss, which shows how **gain versus loss** changes the choice.", "children": ["People played a wheel-of-fortune game with money, choosing each trial between the sure amount and spinning the wheel."]}, {"text": "The typical pattern is **caution with gains** (take the sure thing) and **risk-taking with losses** (take the gamble). How the outcome is perceived matters, not just the odds.", "children": []}], "13": [{"text": "Young children may not get stuck on what an object is usually for, even though problem solving usually improves with age.", "children": ["Children aged 5, 6 and 7 helped a toy bear reach a shelf using objects on a table, with the solution being to turn the box over and stack bricks on it. The other objects started either inside the box (preutilization) or beside it, and the time to offer the box solution was measured.", "A toy bear needed a box turned over as a support to reach a toy on a high shelf, sometimes after the box had been shown as a container."]}, {"text": "Older children, 6 and 7, were **slowed by the container demonstration**. The **5-year-olds were not**, and solved faster than the older children in that condition.", "children": ["With no demonstration, performance just improved with age."]}, {"text": "The likely reason is that **young children treat function as flexible**: whatever the user is trying to do can make something a tool.", "children": ["Older children hold a use more firmly and must restructure the problem to see the box as a support."]}], "14": [{"text": "Ignored speech still **disrupts recall of an ordered list**, and speech with changing syllables does more damage than one repeated syllable.", "children": ["Theories disagree about why: it may corrupt sound-based memory traces, break up order rehearsal, or capture attention."]}, {"text": "The test was whether speech also disrupts memory for **locations**, in children and adults. It **did not**: only **word-like items** suffered.", "children": ["Third graders and adults reconstructed the order of a list of pictured objects or of dot locations, while hearing quiet, a repeated syllable, or changing syllables they were told to ignore. Each person did only one of the two tasks.", "Children were hit harder than adults, even by repeated-syllable speech, although the extra cost of changing syllables was similar in both groups."]}, {"text": "That points to **interference with sound-based codes** and causes trouble for accounts that predict damage to any kind of item.", "children": []}], "15": [{"text": "Writing things down is a way of **taking load off memory**.", "children": ["The question was whether people use it when they most need it, and whether it works."]}, {"text": "When lists got longer than memory can hold, people **used the notepad more and remembered more** because of it.", "children": ["Students heard lists of letters of different lengths and said them back in order, once with memory alone and once with pen and paper available. Working memory capacity was measured with span tasks."]}, {"text": "The expected link to **poor memory ability did not appear**: weaker and stronger memories offloaded alike, and gained alike.", "children": ["That suggests offloading **may help people of many abilities**."]}], "16": [{"text": "The **bat-and-ball puzzle** pulls people to answer 10 cents. Subtracting $1.00 from $1.10 leaves the bat only 90 cents more, so the right answer is **5 cents**.", "children": []}, {"text": "One account says wrong answers come from **swapping in an easier question** without noticing.", "children": ["Evidence for it: wrong reasoners were **less sure of themselves** than on a version without 'more than', as if they sensed a problem."]}, {"text": "Hoover and Healy (2019) found those reasoners often **still remembered the phrase 'more than'** but apparently did not use it, so the error may be **conscious** rather than hidden.", "children": ["People answered a standard problem and a control version without 'more than', rating their confidence each time, and were later asked to recall and recognize the wording, with math problems in between as interference for most.", "Others lost the phrase or stayed confident, so substitution can still happen for some.", "Because the cause cannot be pinned down, they call the confidence drop **error sensitivity**."]}], "17": [{"text": "Two influences on choice were tested together: **wording** (people take the sure thing when outcomes are gains and gamble when they are losses) and **defaults** (people drift to whatever is preselected).", "children": []}, {"text": "When choices were about lives or about money, with the sure or the risky option preselected, **wording kept its usual effect** and the effects of wording and default simply **added up**.", "children": ["Each person was randomly given gain or loss wording with no default, a sure default or a risky default, and chose in a life-or-death scenario and a money scenario. With a default, they were asked whether they would change the preselected option.", "A **risky default pushed people toward risk**, while a **sure default did not make them more cautious** overall.", "Risk was higher when lives were at stake, though involvement also differed from the money case."]}, {"text": "Afterward people said why they thought the option was preselected. Those who saw it as the **most rational choice** followed it most, **expert advice** left people indifferent, and **previous respondents or chance** went with rejecting it.", "children": ["That was an after-the-fact, exploratory question, so beliefs may partly reflect justification of a choice already made."]}], "18": [{"text": "Teens reason about risk about as well as adults when alone, so the extra real-world risk is attributed to **the social setting**.", "children": ["Teens take more risks with friends present than alone, and adults do not."]}, {"text": "In a brain-scan driving game, teens played alone or with friends **watching from another room** and not interacting.", "children": ["When watched, **reward areas became more active** in teens and this went with riskier choices, even though the behavior gap between age groups was not itself firm in a small sample.", "The Stoplight game asked whether to go through a yellow light, risking a crash, or to stop and wait. Adolescents and adults each played alone and with friends watching, and later rated their resistance to peer influence."]}, {"text": "**Control areas did not change with an audience**, so the effect seems to come mainly from a **stronger reward response** rather than weaker self-control, although the review points out that the two systems interact.", "children": ["Peers also push toward immediate rewards, even when only believed to be watching."]}]}, "r22": {"1": [{"text": "The **phonological similarity effect**: a list of items that **sound alike** is recalled worse than a list of items that sound different, even when it is only read silently. Because sound is what matters, **acoustic similarity effect** is arguably the better name.", "children": ["People saw letters one at a time and clicked them in the order shown, with half the lists sounding alike and half sounding different."]}, {"text": "The best interpretation is that people **recode visual input into a speech code**. A purely visual code would cause confusions between look-alikes such as E and F instead.", "children": ["This recoding is the basis of the **phonological loop** in working memory."]}, {"text": "The loop's **phonological store** briefly holds speech-based traces, and its **articulatory control process** converts visual input to speech and refreshes the traces.", "children": ["On some trials people repeated \"one, two, three, four\" aloud while studying (articulatory suppression), and on others they stayed quiet.", "With **articulatory suppression** occupying that process, recoding is blocked and the sound-alike cost disappears for visually presented lists."]}], "2": [{"text": "Roodenrys and colleagues (2002) found that **long-term memory affects short-term recall**: words from a **large neighborhood** are recalled better than words from a **small neighborhood**.", "children": ["A neighborhood is the set of words one letter (orthographic) or one sound (phonological) away; cat has many, hippopotamus has none.", "People saw a sequence of words and clicked them back in the order presented (immediate serial recall)."]}, {"text": "Stored knowledge of words therefore boosts performance on a short-term memory task.", "children": []}, {"text": "Because of this, **memory span** is not a pure measure of short-term memory capacity.", "children": []}], "3": [{"text": "In the **Brown-Peterson task**, people studied consonants and then counted backwards, a **distractor task** that blocked rehearsal. Peterson and Peterson (1959) found that the longer the distraction, the **worse the recall**.", "children": ["Each trial showed three consonants, then a three-digit number to count backwards from by 3, with recall tested after delays of different lengths."]}, {"text": "Counting is so unlike remembering letters that they judged **interference** an unlikely cause.", "children": ["They concluded that **short-term memory (STM)** holds information only briefly and loses it through **decay** unless it is rehearsed."]}, {"text": "Decay is the researchers' conclusion, not the only possible reading; an alternative explanation of the results has been offered.", "children": []}], "4": [{"text": "The **modality effect** is an advantage for the **last one or two items** of a list that is **heard** over one read silently, and it also shows up for lip-read or silently mouthed lists.", "children": ["People heard or saw the digits 1 to 9 and clicked them back in order, half the trials auditory and half visual."]}, {"text": "It strongly shaped ideas about **sensory memory**, a back-up store of **raw, unanalyzed sensory input** that can help recall.", "children": []}, {"text": "Neath and Surprenant (2003) favor the explanation that **hearing adds a further kind of information**, how the list sounds, which helps the final items.", "children": []}], "5": [{"text": "Sperling (1960) argued that the limit on reporting a brief display is on **recall**, not perception.", "children": []}, {"text": "His **partial-report** method cued observers to one part of the display just as it vanished, and whichever part was cued came out nearly intact.", "children": ["A three-by-three matrix of letters flashed briefly, and a tone after it vanished (high, medium or low) cued the top, middle or bottom row, at different delays.", "That implies a **sensory (iconic) store** briefly held almost the whole display."]}, {"text": "A delayed cue lost the advantage, so the store **fades quickly**, and full report is limited because items disappear **while being reported**.", "children": []}], "6": [{"text": "Items are usually recalled in their **correct position**, and when they are not, the errors are **systematic**: the item lands in an **adjacent position**, so the third item is more likely to show up second or fourth than first or last.", "children": ["People saw letters one at a time and clicked them back in order, and each letter's recalled position was compared with its true position."]}, {"text": "So forgetting a position is **not the same as losing the item**. Percent correct alone makes it look like lost information, but people retain **approximate position information**.", "children": []}], "7": [{"text": "Descriptions of mental images are unreliable, so imagery is studied with tasks that require it. Shepard and Metzler (1971) had people judge whether two block shapes were the **same or mirror images** when one was turned; people said they **mentally rotated** one shape to match the other.", "children": ["Two block shapes appeared, identical or mirror images, one rotated by different angles, and people judged same or different as fast as possible.", "The **bigger the turn, the longer the judgment**, and the extra time rose at a **constant rate**."]}, {"text": "Rotating an image takes time, as turning a real object does, which suggests **mental images are much like real images**.", "children": []}, {"text": "The result influenced **theories of mental representation**.", "children": []}], "8": [{"text": "Tversky and Kahneman (1983) showed that probability judgments often differ greatly from objective probability because people use **heuristics**, shortcuts that **trade accuracy for speed**.", "children": []}, {"text": "The **conjunction fallacy** is judging **A and B together** more likely than A alone or B alone, though a combination is **never more likely than** either part.", "children": []}, {"text": "Shafir, Smith and Osherson (1990) had people read a short description of a person and rate how likely certain professions or activities were. People sometimes rated the **combination above one part**, which points to **heuristics**, not probability rules.", "children": ["Ratings ran from impossible to certain, and included single professions or activities and combinations of them."]}], "9": [{"text": "The **Wason Selection Task** asks which cards to turn over to test \"If a card has a D on one side, it has a 3 on the other.\" Only **D and 7** could **falsify** it.", "children": ["People commonly choose D and 3, but the 3 can only **confirm** the rule, and the 7 goes unchecked."]}, {"text": "A familiar rule with identical logic, \"If you borrow my car, you must fill up the tank,\" is **far easier**: the borrowed car and the empty tank are the obvious cards to check.", "children": []}, {"text": "Wason and Shapiro (1971) compared abstract with thematic rules and found that **relevant experience** lets people test a rule, whereas abstract rules leave only **logic**.", "children": ["People chose which two of four cards to turn over to test each rule, half abstract and half thematic."]}], "10": [{"text": "**How a choice is framed shapes the decision.** Kahneman and Tversky (1982) summarized many of these **framing effects**.", "children": []}, {"text": "A framing effect is defined by the **wording or context** changing the choice even though the situations are **otherwise equivalent**.", "children": []}, {"text": "Presented in **two different ways**, the same choice draws different answers: **gain wording** typically leads to the **sure option**, **loss wording** to the **gamble**.", "children": ["People read situations and chose between two options, in one of two question sets that framed the same choices differently."]}], "11": [{"text": "The **Monty Hall 3 Door problem** shows poor intuition about the probability of combinations of events. You pick a door, the host, who always plays fair this way, opens a no-prize door, and the best move is to **switch**.", "children": ["People picked a door, saw another open empty, and chose to stay or switch, and the wins of each strategy were compared over many trials.", "Always switching wins about **two-thirds** of the time, always staying about **one-third**."]}, {"text": "The first pick keeps its **1 in 3** chance, so the other two doors together hold **2 in 3**. The reveal does not change your door's chance, so all **2 in 3** now sits behind the one remaining door.", "children": []}, {"text": "Most people say the two doors are equally likely and that it makes no difference. That is **incorrect**.", "children": []}], "12": [{"text": "In a **framing effect** the same situation described differently draws a different choice, and risky decisions are a prime case.", "children": []}, {"text": "Researchers set a **guaranteed outcome** against a **gamble** with stated chances of winning and losing, and make the guaranteed outcome either a gain or a loss to see what that does to the choice.", "children": ["In a wheel-of-fortune game with money, people chose each trial between the sure amount and spinning the wheel, with stated chances of winning and losing."]}, {"text": "The typical result: with gains people **play it safe** and take the sure thing, while with losses they **gamble**. Perception of the outcome drives the decision, not only the odds.", "children": []}], "13": [{"text": "German and Defeyter (2000) tested whether children show **functional fixedness**, expecting younger children to do worse because problem solving improves with age.", "children": ["Their box task had a toy bear reach a toy on a high shelf by using a box as a support, after the box was or was not shown as a container.", "Children of 5, 6 and 7 used objects on a table to help the bear, with the solution being the box turned over. The other objects started inside the box (preutilization) or beside it, and the time to offer the box solution was measured."]}, {"text": "**Children of 6 and 7 were slowed** by the container demonstration, but **5-year-olds were immune** and solved faster than the older children in that condition.", "children": ["Without the demonstration, children improved with age."]}, {"text": "The authors predicted the immunity because **young children have a more fluid idea of function**.", "children": ["Older children hold function rigidly and must **restructure** the container use to see a support."]}], "14": [{"text": "Leist and colleagues (2022) asked why ignored speech disrupts serial recall, which **changing-state speech** (different syllables) does more than **steady-state speech** (one syllable repeated). The candidate causes were corrupted phonological traces, disrupted order rehearsal, and attention capture.", "children": ["They tested **verbal** items and **spatial** items (locations) in children and adults.", "Third graders and adults reconstructed the order of pictured objects (verbal) or dot locations (spatial) while hearing quiet, a repeated syllable (steady-state) or different syllables (changing-state) to ignore. Each person did one task."]}, {"text": "Speech **did not disrupt spatial recall** in either children or adults, only verbal recall.", "children": ["Children were more impaired than adults relative to silence, but the added cost of changing-state speech was about the same in both groups."]}, {"text": "Leist and colleagues concluded the effect is **specific to verbal material**, which challenges the **attention-capture** and **changing-state** accounts and fits **similarity-based interference** with phonological codes.", "children": []}], "15": [{"text": "Morrison and Richmond (2020) studied **cognitive offloading**, using actions such as writing things down to reduce a task's mental demands, and tested whether people with weaker working memory offload more.", "children": ["Students heard lists of letters and said them back in order, in a no-choice block (memory alone) and a choice block (pen and paper available), and completed working memory span tasks."]}, {"text": "Offloading helped most at **high loads**, and people offloaded more as the load rose.", "children": []}, {"text": "Memory ability did **not** predict who offloaded, and ability did not predict the benefit, so offloading **may be a compensatory strategy** across abilities.", "children": []}], "16": [{"text": "The **bat-and-ball problem**: 10 cents feels right, but 5 cents is correct because the bat must cost a dollar more than the ball.", "children": []}, {"text": "One account of the error is **attribute substitution**: reasoners neglect 'more than' and answer an easier question.", "children": ["Support for it: wrong reasoners were **less confident** on the standard problem than on a control version without 'more than' (**substitution sensitivity**)."]}, {"text": "Hoover and Healy (2019) found wrong reasoners mostly **remembered 'more than'** but apparently did not use its meaning, evidence for a **conscious error process**.", "children": ["People answered a standard problem and a control without 'more than' and rated their confidence, then were asked to recall and recognize the wording, with math problems as interference for most.", "Because some lost the phrase and many stayed confident, substitution may still occur for some.", "They prefer **error sensitivity** because they cannot be sure the error was substitution."]}], "17": [{"text": "Giuliani and colleagues (2023) joined two influences on choice in one study: the **framing effect** (the sure option for gains, the risky option for losses) and the **default effect** (a tendency to take the preselected option).", "children": ["People made life-or-death and financial choices with no default, a **sure default**, or a **risky default**.", "People were randomly assigned gain or loss wording with no default, a sure default or a risky default, and chose in a life-or-death and a money scenario. With a default, they were asked whether to change the preselected option, and afterward gave a reason for why it was preselected."]}, {"text": "They found a **classic framing effect** and more risk taking with lives than money, though the lives concerned people elsewhere and the money was the participant's own.", "children": ["A **risky default raised risk taking** while a **sure default did not raise risk aversion** overall.", "Framing and default effects were **additive**."]}, {"text": "In an exploratory question after the choice, belief in the default as **most rational** went with following it most, **expert advice** with indifference, and **previous respondents or chance** with rejection.", "children": ["Beliefs may partly be justification of a choice already made."]}], "18": [{"text": "Albert, Chein and Steinberg (2013) point to the peer context: adolescents, but not adults, take more risks with peers than alone.", "children": ["Their model is a **maturational gap** between a peer-primed **reward system** and a slowly maturing **cognitive-control system**."]}, {"text": "Chein and colleagues (2011) scanned a **driving game** played alone or watched by friends, and found adolescents took significantly more risks when watched, though the age-by-context difference on behavior was not itself significant in this small sample.", "children": ["Adolescents, young adults and adults played the Stoplight driving game in a scanner, deciding at each yellow light to go (risking a crash) or stop, once alone and once with friends watching, and later rated their resistance to peer influence.", "Reward regions (**ventral striatum, orbitofrontal cortex**) were more active in adolescents when peers watched, going with risky decisions."]}, {"text": "**Cognitive-control regions did not change with peers**, so the authors concluded the effect works mainly through **reward circuitry**, though the review points out that the two systems interact.", "children": ["Peers also raise preference for immediate rewards, even when only believed present."]}]}};
window.C15_MEDIA = {"sections": {"1": {"credit": "AuBuchon, Wagner (2023), Fig. 1", "description": "Serial recall of similar and dissimilar word lists; published phonological-similarity results.", "doi": "10.3758/s13421-023-01418-2", "source": "https://europepmc.org/articles/PMC10187497", "videos": [], "kind": "related"}, "2": {"credit": "Ballot, Robert, Dujardin et al. (2023), Fig. 1", "description": "Lexical skills and neighborhood size: original recall results from a related word-memory experiment. (related variant, not the exact CogLab task)", "doi": "10.3758/s13421-023-01487-3", "source": "https://europepmc.org/articles/PMC11021223", "videos": [], "kind": "related"}, "3": {"credit": "Siffredi et al. (2017), Fig. 1", "description": "Encoding, concurrent task, and retrieval in a modified Brown-Peterson experiment; not the exact CogLab task.", "doi": "10.1371/journal.pone.0179959", "source": "https://europepmc.org/articles/PMC5509143", "videos": [{"id": "k02Ok8imYAA", "title": "3 sec Brown Peterson Task SD 480p", "channel": "Working Memory and Language", "note": "Brown-Peterson trial with a 3-second distractor delay (short demonstration clip). Related demonstration; not the original study."}], "kind": "related"}, "4": {"credit": "Grenfell-Essam, Ward, Tan (2017), Figure 1", "description": "Auditory versus visual serial-position curves in immediate free and serial recall; published modality-effect results. Intact original figure extracted from the author manuscript, page 69.", "doi": "10.1037/xlm0000430", "source": "https://europepmc.org/articles/PMC5729966", "videos": [], "kind": "related"}, "5": {"credit": "Clausen & Kattner (2024), Fig. 1", "description": "Trial sequence in an iconic-memory task with a post-display location cue; a related partial-report variant.", "doi": "10.1007/s00426-024-02024-w", "source": "https://europepmc.org/articles/PMC11522187", "videos": [{"id": "GkZNHe49GcA", "title": "Iconic Memory Test (demo of a classic psychophysics experiment by George Sperling on VSTM)", "channel": "Axon", "note": "Demonstration of Sperling’s iconic memory experiment. Related demonstration; not the original study."}, {"id": "SIWfrlAQ7_A", "title": "Whole Partial Report Sperling, 1960", "channel": "Arlo Clark-Foos", "note": "University course demonstration of whole and partial report. Related demonstration; not the original study."}], "kind": "related"}, "6": {"credit": "Ward, Beaman (2024), Figure 6.", "description": "Input versus output serial positions. Published figure using Osth and Dennis (2015) data; not newly plotted.", "doi": "10.1177/17470218241282093", "source": "https://europepmc.org/articles/PMC11783987", "videos": [], "kind": "related"}, "7": {"credit": "Kozaki (2022), Fig. 1", "description": "Trial display of a Shepard-and-Metzler-style three-dimensional mental rotation task (two block figures, respond valid or invalid, i.e. same or mirror image); related variant, not the exact CogLab task.", "doi": "10.1186/s40101-022-00314-z", "source": "https://europepmc.org/articles/PMC9650873", "videos": [{"id": "VlBRj7qwGGk", "title": "Mental Rotation Test", "channel": "Professor LaMarr", "note": "A mental rotation test with 3D shapes. Related demonstration; not the original study."}], "kind": "related"}, "8": {"credit": "Wojciechowski & Pothos (2018), Fig. 1", "description": "Procedure of a conjunction-fallacy experiment (single conjunctive rating vs. separate ratings of each component); related variant using legal cases, not the exact CogLab profession-rating task and not the Linda problem itself.", "doi": "10.3389/fpsyg.2018.00391", "source": "https://europepmc.org/articles/PMC5895783", "videos": [], "kind": "related"}, "9": {"credit": "Rossi, Cassotti & Moutier (2015), Fig. 2A", "description": "Four-card Wason selection task display with the rule \"If there is an A on one side of the card, then there is a 3 on the other\" and cards A, D, 3, 7, plus the logical (A, 7) versus matching-bias answers; the abstract version of the task, shown in a related study rather than the CogLab interface. Panel B (a learning-phase apparatus) is also in the image.", "doi": "10.1371/journal.pone.0123024", "source": "https://europepmc.org/articles/PMC4388638", "videos": [], "kind": "related"}, "10": {"credit": "Zhen & Yu (2016), Fig. 2", "description": "Trial structure of a vignette-based framing task: imagine 600 people infected by a fatal disease, choose a sure option or a gamble, framed as lives saved (positive) or lives lost (negative); an Asian-disease-style framing task, related variant, not the exact CogLab questions.", "doi": "10.1038/srep30071", "source": "https://europepmc.org/articles/PMC4951804", "videos": [], "kind": "related"}, "11": {"credit": "Tubau, Aguilar-Lleyda & Johnson (2015), Fig. 1", "description": "Schematic of the Monty Hall dilemma: pick one of three doors, the host opens a non-prize door, then stick or switch; shows correct (2/3) versus incorrect (1/2) reasoning. Schematic of the task from a review/perspective article, not the CogLab simulation.", "doi": "10.3389/fpsyg.2015.00353", "source": "https://europepmc.org/articles/PMC4379739", "videos": [], "kind": "related"}, "12": {"credit": "Gosling & Moutier (2017), Fig. 1", "description": "Trial display of a financial sure-versus-gamble task: an initial amount, then a sure option (keep or lose a fixed amount) against a risky pie-chart gamble with stated win/lose probabilities, framed as gain or loss; related variant of the CogLab wheel-of-fortune style task, not the exact CogLab task.", "doi": "10.3389/fpsyg.2017.00081", "source": "https://europepmc.org/articles/PMC5298953", "videos": [], "kind": "related"}, "13": {"credit": "German & Defeyter (2000), Figure 1", "description": "Mean time to solution by age and pre-utilization condition; assigned-article results figure.", "doi": "10.3758/BF03213010", "source": "", "videos": [{"id": "d_PjIo0nVGg", "title": "The Candle Problem - Vita Creativity Company", "channel": "Cavin Weber", "note": "Candle problem demonstration with an adult; the study itself tested children. Related demonstration; not the original study."}], "kind": "article"}, "14": {"credit": "Leist, Lachmann, Schlittmeier, Georgi & Klatte (2022/2023), Fig. 1", "description": "Construction of the spatial dot sequences; assigned-article task figure.", "doi": "10.3758/s13421-022-01359-2", "source": "", "videos": [], "kind": "article"}, "15": {"credit": "Morrison & Richmond (2020), Fig. 1", "description": "Trial sequence of the auditory letter short-term memory task; assigned-article task figure.", "doi": "", "source": "", "videos": [], "kind": "article"}, "16": {"credit": "Hoover & Healy (2019), Figure 1", "description": "Confidence and opinion scores, standard vs control bat-and-ball; assigned-article results figure.", "doi": "10.1037/dec0000107", "source": "", "videos": [], "kind": "article"}, "17": {"credit": "Giuliani et al. (2023), Fig. 1", "description": "Additive effects of frame and scenario on risky choice; assigned-article results figure.", "doi": "10.1007/s00426-022-01726-3", "source": "", "videos": [], "kind": "article"}, "18": {"credit": "Albert, Chein & Steinberg (2013), Fig. 1", "description": "Schematic of the Stoplight driving game used in the peer-influence experiment; assigned-article task figure.", "doi": "10.1177/0963721412471347", "source": "", "videos": [], "kind": "article"}}};
(()=>{const b=window.SECOND_HALF,c=window.C15_BANK;if(!b||!c)return;const id=c.collection.id;
 b.collections=b.collections.filter(x=>x.id!==id).concat([c.collection]);
 b.questions=b.questions.filter(q=>q.module!==id).concat(c.questions);
 b.modules=b.modules.filter(m=>m!==id).concat([id]);
 b.lectureNumbers[id]=c.lectureNumber;b.revision=c.revision;
 for(const key of ['topics','coreReview','experiments'])b[key]=b[key].filter(g=>g.module!==id).concat(c[key]);})();
